local config = {
  ui_story_5065_50650101_1_dialog_content = "Selamat pagi, instruktur!",
  ui_story_5065_50650101_2_dialog_content = "Selamat pagi. Apakah kamu Paloma, peserta magang yang direkomendasikan oleh Akademi Dawn?",
  ui_story_5065_50650101_3_dialog_content = "Ya, tetapi orang-orang biasanya hanya memanggilku Pam. Saya sangat berterima kasih kepada Akademi dan Kuil Lumopolis atas kesempatan pelatihan berharga ini!",
  ui_story_5065_50650101_4_dialog_content = "Pam, apa kamu tahu tentang apa itu Kuil Lumopolis?",
  ui_story_5065_50650101_5_dialog_content = "(Menguji pengetahuan saya sudah...?)",
  ui_story_5065_50650101_6_dialog_content = "(Baguslah aku sudah menghafal segala hal tentang Lumopolis Temple sejak lama!)",
  ui_story_5065_50650101_7_dialog_content = "Ahem... Lumopolis Temple adalah tempat paling suci dan sakral di seluruh Lumopolis!",
  ui_story_5065_50650101_8_dialog_content = "Kuil membawa pengabdian kita kepada Dewa Cahaya ke langit di atas, dan memberkati orang-orang di bawah dengan kebijaksanaan dan pencerahan.",
  ui_story_5065_50650101_9_dialog_content = "Kuil ini tidak hanya mengawasi setiap gereja di Lumopolis, tetapi juga menyimpan tiga relik suci: sebuah pedang, sebuah kitab, dan sebuah tongkat!",
  ui_story_5065_50650101_10_dialog_content = "Ketiga peninggalan ini mewakili Ksatria Lumo, Akademi Dawn, dan Balai Kehakiman masing-masing.",
  ui_story_5065_50650101_11_dialog_content = "Tak heran kamu rekomendasi dari Dawn Academy; kamu pasti sudah melakukan pekerjaan rumah dengan baik.",
  ui_story_5065_50650101_12_dialog_content = "Pengetahuan teoritis memang bagus, tetapi tanpa pengalaman praktis, itu hanyalah angan-angan. Selanjutnya, saya akan meminta Anda terlibat dalam urusan berbagai afiliasi kuil.",
  ui_story_5065_50650101_13_dialog_content = "Anda perlu cepat belajar cara menangani berbagai tugas dalam waktu yang terbatas, dan memahami sepenuhnya arti penting kuil bagi Lumopolis.",
  ui_story_5065_50650101_14_dialog_content = "Kamu mungkin menghadapi tantangan dan bahkan kemunduran, tapi tidak apa-apa; kamu bisa memilih untuk menyerah kapan saja.",
  ui_story_5065_50650101_15_dialog_content = "Aku... Aku takkan pernah berhenti!",
  ui_story_5065_50650101_16_dialog_content = "Bagus, semoga tindakanmu sesuai dengan tekadmu.",
  ui_story_5065_50650101_17_dialog_content = "Kebetulan bahwa Hall of Justice memerlukan bantuan tambahan akhir-akhir ini. Mengapa Anda tidak mulai dengan membantu di sana?",
  ui_story_5065_50650101_18_dialog_content = "Setelah Anda berada di Hall of Justice, temukan Hakim Junior. Dia akan memberi tahu Anda apa yang akan terjadi selanjutnya.",
  ui_story_5065_50650101_19_dialog_content = "Demi White Night! Semoga May Dewa Cahaya membawa keberuntungan untukmu.",
  ui_story_5065_50650102_1_dialog_content = "Ugh, kenapa dia masih belum di sini? Aku akan menuduhnya melakukan kejahatan terlambat dan memberinya hukuman yang paling keras!",
  ui_story_5065_50650102_2_dialog_content = "Apakah benar-benar kejahatan untuk terlambat di Lumopolis...?",
  ui_story_5065_50650102_3_dialog_content = "Lihat, saya seorang hakim, jadi jika saya bilang itu kejahatan, itu kejahatan. Kamu tidak punya hak untuk mempertanyakannya.",
  ui_story_5065_50650102_4_dialog_content = "A-Aku mengerti! Aku tidak bermaksud menyanggahmu, jadi tolong maafkan aku!",
  ui_story_5065_50650102_5_dialog_content = "Karena Anda seorang the Junior Judge juga pasti tahu, bukan?",
  ui_story_5065_50650102_6_dialog_content = "Ehem, jadi kamu penggemar dia?",
  ui_story_5065_50650102_7_dialog_content = "Er... Dalam beberapa hal, ya. Bekerja di Balai Kehakiman dan melewati penghakiman Dewa Cahaya adalah salah satu kehormatan terbesar yang bisa diraih oleh seseorang.",
  ui_story_5065_50650102_8_dialog_content = "Meskipun banyak orang mengatakan bahwa Hakim Junior memiliki peringkat yang terlalu rendah dan mudah tersinggung, saya sangat percaya...",
  ui_story_5065_50650102_9_dialog_content = "A-Apa?! Apakah kamu bilang saya memiliki peringkat rendah dan temperamen buruk? Beraninya kamu!",
  ui_story_5065_50650102_10_dialog_content = "Um, Anda bukan kebetulan Hakim Junior, bukan? Tolong biarkan saya menjelaskan, karena saya belum menyelesaikan kalimat saya...",
  ui_story_5065_50650102_11_dialog_content = "Saya sangat percaya bahwa siapa pun yang bekerja untuk Hall of Justice pasti adalah seorang jenius yang layak dihormati! Itulah mengapa saya sangat percaya dan menghormati Anda!",
  ui_story_5065_50650102_12_dialog_content = "Huh, kamu cepat tanggap. Kamu direkomendasikan oleh Lumopolis Temple, kan? Serahkan itu.",
  ui_story_5065_50650102_13_dialog_content = "Serahkan apa...?",
  ui_story_5065_50650102_14_dialog_content = "Hadiah untuk \"Mentor di Balai Kehakiman.\" Kamu tidak lupa menyiapkannya, bukan?",
  ui_story_5065_50650102_15_dialog_content = "S-saya tidak tahu kalau saya harus menyiapkan hadiah untuk kamu...",
  ui_story_5065_50650102_16_dialog_content = "Astaga, kenapa siswa yang direkomendasikan oleh Dawn Academy semakin buruk setiap tahunnya?",
  ui_story_5065_50650102_17_dialog_content = "Yasudah, lupakan saja. Mari langsung ke intinya.",
  ui_story_5065_50650102_18_dialog_content = "Saya baru saja mendapatkan kasus, ahem... jenis kasus yang sangat dihargai oleh Ketua Hakim.",
  ui_story_5065_50650102_19_dialog_content = "Ada geng pengacau dari Lumopolis Bawah yang mencuri barang berharga dari banyak rumah tangga bangsawan, dan mereka masih bersembunyi di Lumopolis!",
  ui_story_5065_50650102_20_dialog_content = "Sayangnya, saya belum berhasil menangkap mereka, jadi kasus ini masih tertunda di meja saya, sangat mempengaruhi penilaian kinerja saya...",
  ui_story_5065_50650102_21_dialog_content = "Ahem, jangan salah paham; menangkap mereka bukanlah hal yang sulit. Saya hanya ingin meninggalkan kasus ini untuk seorang pemula seperti kamu sebagai kesempatan.",
  ui_story_5065_50650102_22_dialog_content = "Sekarang, saya secara resmi menyerahkan kasus ini kepada kamu. Kamu bisa membantu saya menangkap pencuri-pencuri keji itu, kan?",
  ui_story_5065_50650102_23_dialog_content = "Y-Kamu mempercayakan ini kepadaku? Tapi aku baru saja menjadi trainee! Aku tidak tahu bagaimana cara menanganinya...",
  ui_story_5065_50650102_24_dialog_content = "Ini bukan ini bu k tool For the first to the language in #8217;re for that is in the ",
  ui_story_5065_50650102_25_dialog_content = "Beginilah cara kerja; semua orang tumbuh melalui pengalaman langsung, mengerti?",
  ui_story_5065_50650102_26_dialog_content = "Saya mengerti. Baiklah, saya paham! Sepertinya aku masih harus banyak belajar dari Anda, Pak.",
  ui_story_5065_50650102_27_dialog_content = "Hmm, sangat baik. Kabarnya para pencuri ini akan menyamar di dekat Shuttle Hub di Taman Lumopolis hari ini.",
  ui_story_5065_50650102_28_dialog_content = "Apa pun yang kamu lakukan, jangan biarkan mereka pergi! Eh... siapa namamu lagi?",
  ui_story_5065_50650102_29_dialog_content = "Paloma!",
  ui_story_5065_50650102_30_dialog_content = "Paloma, saatnya bergerak! Pertemuan berikutnya, aku berharap melihatmu membawa pencuri yang telah kamu tangkap.",
  ui_story_5065_50650103_1_dialog_content = "Salam! Maafkan saya, tetapi apakah Anda melihat orang yang mencurigakan hari ini?",
  ui_story_5065_50650103_2_dialog_content = "Orang-orang mencurigakan? Saya rasa tidak ada...",
  ui_story_5065_50650103_3_dialog_content = "Maaf, aku terburu-buru. Pesawat akan segera lepas landas. Mungkin kamu harus bertanya kepada orang lain.",
  ui_story_5065_50650103_4_dialog_content = "(Ini aneh, seharusnya bukan waktunya para penjaga berganti shift, jadi mengapa penjaga ini berbuat sesuka hati?)",
  ui_story_5065_50650103_5_dialog_content = "(Jangan-jangan...?!)",
  ui_story_5065_50650103_6_dialog_content = "Sebentar, Pak!",
  ui_story_5065_50650103_7_dialog_content = "...!!!",
  ui_story_5065_50650103_8_dialog_content = "(Dia kabur... Apakah dia salah satu dari pencuri yang menyamar itu?)",
  ui_story_5065_50650103_9_dialog_content = "Berhenti!",
  ui_story_5065_50650104_1_dialog_content = "Hah? Kamu sudah kembali?",
  ui_story_5065_50650104_2_dialog_content = "Yang Terhormat, saya menangkap salah satu tersangka! Dia menyamar sebagai Lumo Guard dan hampir kabur dengan pesawat terbang!",
  ui_story_5065_50650104_3_dialog_content = "Kamu? Menangkap mereka? Buronan itu? Ini... sulit dipercaya...",
  ui_story_5065_50650104_4_dialog_content = "Oh tidak, yang aku maksud, bukankah menurutmu misi ini cukup sederhana?",
  ui_story_5065_50650104_5_dialog_content = "Lepaskan aku! Apakah kamu punya bukti?!",
  ui_story_5065_50650104_6_dialog_content = "Bukti? Bukankah itu sesuatu yang bisa kamu tanam sebanyak yang kamu inginkan?",
  ui_story_5065_50650104_7_dialog_content = "Apa maksud Anda dengan itu, Pak...?",
  ui_story_5065_50650104_8_dialog_content = "Ahem, maksud saya, saya akan menginterogasi pencuri ini secara menyeluruh, membuat mereka mengaku dan menghadapi konsekuensinya.",
  ui_story_5065_50650104_9_dialog_content = "Paloma, lihat dan pelajari saja.",
  ui_story_5065_50650104_10_dialog_content = "Namun…",
  ui_story_5065_50650104_11_dialog_content = "Tapi apa? Jangan pikir menangkap pencuri memberimu hak untuk membuat permintaan yang kurang ajar di hadapanku.",
  ui_story_5065_50650104_12_dialog_content = "Tapi pencuri itu berhasil melepaskan diri dari borgolmu dan melarikan diri!",
  ui_story_5065_50650104_13_dialog_content = "Kejar dia! Sekarang!",
  ui_story_5065_50650104_14_dialog_content = "Ini keterlaluan!",
  ui_story_5065_50650104_15_dialog_content = "Pak, saya berhasil menangkap pencuri lagi, jadi tolong jangan bersedih! Apakah kita harus menggunakan lebih dari satu pasang borgol pada dia?",
  ui_story_5065_50650104_16_dialog_content = "Hmph, tidak perlu. Aku akan mengurungnya langsung di penjara!",
  ui_story_5065_50650104_17_dialog_content = "Kamu cukup baik hari ini, tidak mengecewakan. Tapi, biar aku yang melanjutkan; kamu tidak perlu khawatir tentang itu.",
  ui_story_5065_50650201_1_dialog_content = "Huh... Ini tidak bagus...",
  ui_story_5065_50650201_2_dialog_content = "Apa yang terjadi, Yang Mulia? Adakah yang bisa saya bantu?",
  ui_story_5065_50650201_3_dialog_content = "Ah, kamu datang tepat waktu! Hari ini giliranku untuk membuka pintu kantor sebelum semua orang tiba di sini.",
  ui_story_5065_50650201_4_dialog_content = "Tapi kunci kantor itu tertelan oleh ikan di kolam!",
  ui_story_5065_50650201_5_dialog_content = "Sebuah ikan menelan kunci? Semoga tidak apa-apa...",
  ui_story_5065_50650201_6_dialog_content = "Ada begitu banyak ikan dan aku tidak bisa membedakan mana yang... Tunggu, seharusnya kamu lebih peduli padaku, bukan?",
  ui_story_5065_50650201_7_dialog_content = "M-maksud saya, apakah Anda baik-baik saja, Pak?",
  ui_story_5065_50650201_8_dialog_content = "Apakah saya terlihat baik-baik saja? Saya harus membuka kantor sebelum semua orang datang, atau penilaian kinerja saya untuk bulan ini akan... Ahem... Pokoknya, kebetulan saya punya tugas untuk kamu.",
  ui_story_5065_50650201_9_dialog_content = "Dawn Academy, Lumopolis Courtyard, dan Lower Lumopolis masing-masing memiliki patung skala. Mereka terlihat seperti yang ada di depan Hall of Justice.",
  ui_story_5065_50650201_10_dialog_content = "Psst! Simpan ini di antara kita... Jika kamu menyelesaikan misi tentang timbangan, itu akan menghasilkan Pemberat Emas.",
  ui_story_5065_50650201_11_dialog_content = "Selama Anda mengumpulkan timbangan emas dari tiga patung timbangan yang berbeda, Anda dapat menggabungkannya di timbangan di depan Hall of Justice untuk membuat kunci!",
  ui_story_5065_50650201_12_dialog_content = "Tugas Anda adalah pergi dan membantu saya mengumpulkan ketiga timbangan emas ini.",
  ui_story_5065_50650201_13_dialog_content = "Anda tidak ikut denganku, Pak?",
  ui_story_5065_50650201_14_dialog_content = "Yah, saya memiliki hal-hal lain yang harus diurus... Anda tahu, jika ada seseorang yang datang, saya harus mencari alasan untuk mengusir mereka pergi.",
  ui_story_5065_50650201_15_dialog_content = "Ayo jalan! Cepat!",
  ui_story_5065_50650202_1_dialog_content = "Sebuah pemberat emas benar-benar keluar!",
  ui_story_5065_50650202_2_dialog_content = "Terima kasih atas pengetahuan yang terkumpul selama beberapa hari ini, quest-quest ini sama sekali tidak sulit.",
  ui_story_5065_50650202_3_dialog_content = "Dengan kecepatan ini, aku harus tepat waktu... Aku harus bergegas ke set timbangan berikutnya!",
  ui_story_5065_50650203_1_dialog_content = "Itu pemberat emas lainnya!",
  ui_story_5065_50650203_2_dialog_content = "Ini bagus, sekarang saya hanya butuh satu lagi dan setnya akan lengkap.",
  ui_story_5065_50650204_1_dialog_content = "Akhirnya saya berhasil mengumpulkan ketiga pemberat emas!",
  ui_story_5065_50650204_2_dialog_content = "Bisakah saya tepat waktu? Saya harus bergegas kembali dan memberikan ini kepada Hakim Junior...",
  ui_story_5065_50650205_1_dialog_content = "*Mendengkur*",
  ui_story_5065_50650205_2_dialog_content = "Saya tidak terlambat, bukan, Pak?",
  ui_story_5065_50650205_3_dialog_content = "Hah?! Kunci kantor diambil oleh trainee yang bernama Paloma!",
  ui_story_5065_50650205_4_dialog_content = "Eh, maaf jika saya membangunkan Anda, Pak, tapi saya tidak pernah mengambil kuncinya...",
  ui_story_5065_50650205_5_dialog_content = "Ahem, jadi kamu ya? Saya pikir itu salah satu rekan kerja saya. Apakah kamu sudah menyelesaikan tugas yang saya berikan?",
  ui_story_5065_50650205_6_dialog_content = "Jika kamu gagal membawa kembali tiga timbangan emas, aku tidak akan bisa mendapatkan kuncinya. Jadi, tidak berlebihan jika aku bilang kamu telah mengambil kunci itu, kan?",
  ui_story_5065_50650205_7_dialog_content = "Aku sudah membawa kembali ketiga pemberat emas yang kamu minta.",
  ui_story_5065_50650205_8_dialog_content = "Kamu... maksud kamu, kamu benar-benar menyelesaikan quest-quest itu?",
  ui_story_5065_50650205_9_dialog_content = "Apakah trainee baru saja menyelesaikan quest yang bahkan saya sendiri tidak bisa tangani?",
  ui_story_5065_50650205_10_dialog_content = "Maksudku... tidak bisa dipungkiri bahwa penilaianku terhadap orang sepertinya memang tepat!",
  ui_story_5065_50650205_11_dialog_content = "Jangan khawatir. Aku akan mengucapkan kata-kata baik untukmu di depan mentormu.",
  ui_story_5065_50650205_12_dialog_content = "Terima kasih atas dukungan Anda, Hakim Junior!",
  ui_story_5065_50650301_1_dialog_content = "Selamat pagi, Yang Mulia!",
  ui_story_5065_50650301_2_dialog_content = "Nah, Pam, aku sudah menunggumu.",
  ui_story_5065_50650301_3_dialog_content = "M-Maaf... Apakah aku terlambat lagi?",
  ui_story_5065_50650301_4_dialog_content = "Kamu memang melewatkan momen mendebarkan saat saya menginterogasi pencuri itu, tapi tidak apa-apa. Yang penting tahu bahwa...",
  ui_story_5065_50650301_5_dialog_content = "... setelah interogasi brilian saya, pencuri yang kita tangkap beberapa hari yang lalu akhirnya membuka rahasia tentang keberadaan rekan-rekannya!",
  ui_story_5065_50650301_6_dialog_content = "Demi White Night! Bagaimana kamu bisa melakukannya?! Dia belum memberi kita satu petunjuk pun beberapa hari terakhir ini!",
  ui_story_5065_50650301_7_dialog_content = "Hmph, jika kamu ingin tahu, nanti aku bisa mengajari kamu.",
  ui_story_5065_50650301_8_dialog_content = "Sekarang, kita perlu memanfaatkan keuntungan kita dan menangkap sisa pencuri-pencuri itu!",
  ui_story_5065_50650301_9_dialog_content = "Para penjahat sialan itu akan menunggu pertemuan di dekat patung timbangan di Halaman Lumopolis hari ini. Cepat tangkap mereka!",
  ui_story_5065_50650301_10_dialog_content = "Sesuai perintah, Yang Mulia!",
  ui_story_5065_50650302_1_dialog_content = "Mengenakan penyamaran yang sama lagi, ya?",
  ui_story_5065_50650302_2_dialog_content = "Siapa kamu?! Beraninya kamu tidak sopan kepada penjaga Lumopolis?",
  ui_story_5065_50650302_3_dialog_content = "Aku... Aku tidak akan membiarkan kamu mencemarkan nama penjaga kota kami lebih lama lagi!",
  ui_story_5065_50650303_1_dialog_content = "Yang Mulia, saya telah membawa kembali kaki tangan pencuri ini!",
  ui_story_5065_50650303_2_dialog_content = "Kenapa hanya ada satu saja?!",
  ui_story_5065_50650303_3_dialog_content = "Y-Yah, saya hanya melihat satu orang mencurigakan di Halaman Lumopolis.",
  ui_story_5065_50650303_4_dialog_content = "Mengapa kamu hanya memeriksa Halaman Lumopolis saja? Mulai malas, ya?",
  ui_story_5065_50650303_5_dialog_content = "Tidak pernahkah saya sebutkan bahwa ada kaki tangan lain yang bersembunyi di Lower Lumopolis?",
  ui_story_5065_50650303_6_dialog_content = "K-kau mengatakan itu, Pak?",
  ui_story_5065_50650303_7_dialog_content = "Wow, begitu ada masalah, kamu sudah mencoba menyalahkan atasanmu? Kenapa tidak pertimbangkan jika kamu salah ingat?",
  ui_story_5065_50650303_8_dialog_content = "Sangat muda, tapi sudah mengambil kebiasaan buruk ini. Siapa yang tahu apa yang akan terjadi pada dirimu di masa depan?",
  ui_story_5065_50650303_9_dialog_content = "Maaf. Mungkin memang benar aku tidak mengingat hal-hal dengan benar...",
  ui_story_5065_50650303_10_dialog_content = "Tapi jangan khawatir, Pak. Saya akan segera turun ke Lower Lumopolis dan menangkap para penjahat yang tersisa!",
  ui_story_5065_50650304_1_dialog_content = "Satu lagi penjaga sendirian yang melihat-lihat dengan curiga...",
  ui_story_5065_50650304_2_dialog_content = "Dia mungkin menyamar sebagai penjaga Lumopolis, tetapi niat kriminalnya tidak bisa disembunyikan.",
  ui_story_5065_50650304_3_dialog_content = "A-Apa yang kamu lakukan?!",
  ui_story_5065_50650304_4_dialog_content = "Mengantarmu ke tempat yang seharusnya.",
  ui_story_5065_50650305_1_dialog_content = "Hmmm, itu benar.",
  ui_story_5065_50650305_2_dialog_content = "Mengingat kamu telah mengumpulkan semua kaki tangan pencuri itu, aku bisa membiarkan insiden yang tidak menyenangkan ini berlalu hari ini.",
  ui_story_5065_50650305_3_dialog_content = "Terima kasih atas pengertian Anda, Yang Mulia!",
  ui_story_5065_50650305_4_dialog_content = "Apakah ada hal lain yang bisa saya bantu untuk Anda?",
  ui_story_5065_50650305_5_dialog_content = "Pengadilan yang akan datang cukup berbeda dari menangkap penjahat; mereka menuntut kecerdasan dan keterampilan yang lebih besar.",
  ui_story_5065_50650305_6_dialog_content = "Bahkan jika aku memberitahumu triknya, kamu tidak akan memahaminya dalam waktu singkat. Selain itu, seorang peserta pelatihan tidak perlu terlibat dalam hal-hal yang terlalu rumit.",
  ui_story_5065_50650305_7_dialog_content = "I-Begitukah...? Tapi Pak, jika Anda memberi saya kesempatan, saya berjanji tidak akan mengecewakan Anda!",
  ui_story_5065_50650305_8_dialog_content = "Cukup untuk hari ini. Kamu belum lelah? Pulang saja, dan aku akan mengurus sisanya!",
  ui_story_5065_50650305_9_dialog_content = "Hah? Apakah kamu menunjukkan perhatianmu dengan mengirimku pulang untuk beristirahat?",
  ui_story_5065_50650305_10_dialog_content = "Hah? Eh, ehem... Ya, itu persis yang kumaksudkan.",
  ui_story_5065_50650305_11_dialog_content = "Terima kasih banyak, Pak!",
  ui_story_5065_50650305_12_dialog_content = "Kamu benar. Mimpi Paloma telah menjadi terjalin dengan mimpiku sendiri...",
  ui_story_5065_50650305_13_dialog_content = "Lebih tepatnya, orang yang tinggal di sini yang menolak untuk bangun adalah Pam yang kamu temui dalam mimpimu.",
  ui_story_5065_50650305_14_dialog_content = "Pam... Apakah dia sedang bermimpi tentang saat pertama kali menjadi trainee?",
  ui_story_5065_50650305_15_dialog_content = "Ini adalah saat paling bahagia dalam hidupnya.",
  ui_story_5065_50650305_16_dialog_content = "Haruskah aku memberitahu Pam yang sebenarnya? Aku tidak tega merusak kebahagiaannya...",
  ui_story_5065_50650305_17_dialog_content = "Tetapi jika dia tidak bangun, kamu juga tidak akan punya cara untuk bangun.",
  ui_story_5065_50650305_18_dialog_content = "Pam, kamu lah yang membantu saya menyadari bahwa mimpi ini hanyalah ilusi belaka. Pada akhirnya, kita semua perlu bangun dan menghadapi diri kita yang sebenarnya.",
  ui_story_5065_50650305_19_dialog_content = "Kali ini, giliran aku yang akan membangunkanmu.",
  ui_story_5065_50650401_1_dialog_content = "Selamat pagi, Yang Mulia!",
  ui_story_5065_50650401_2_dialog_content = "Oh, Pam, kamu tepat waktu.",
  ui_story_5065_50650401_3_dialog_content = "Aku baru menyadari bahwa aku punya beberapa buku yang dipinjam dari Dawn Academy di sini, dan tanggal pengembaliannya sudah hampir tiba.",
  ui_story_5065_50650401_4_dialog_content = "Bantu aku mengembalikannya, lalu pinjamkan beberapa buku yang sama.",
  ui_story_5065_50650401_5_dialog_content = "Apakah kamu ingin terus meminjam buku-buku ini?",
  ui_story_5065_50650401_6_dialog_content = "Tidak, saya sudah memperbarui buku-buku ini sepuluh kali, dan saya tidak bisa memperbarui mereka lagi.",
  ui_story_5065_50650401_7_dialog_content = "Baguslah Dawn Academy punya banyak buku yang sama. Ambilkan saja salinan yang berbeda untukku.",
  ui_story_5065_50650401_8_dialog_content = "Aku mengerti... Aku penasaran, jenis buku apa yang layak diperpanjang sepuluh kali berturut-turut?",
  ui_story_5065_50650401_9_dialog_content = "\"Semangat Debat Hukum,\" \"Ikhtisar Hukum\"... Buku-buku ini terlihat sangat esoteris! Apa sebenarnya yang mereka bahas?",
  ui_story_5065_50650401_10_dialog_content = "Yah, um... kalau kamu ingin tahu, aku bisa menulis rangkuman untukmu, tapi mungkin butuh waktu.",
  ui_story_5065_50650401_11_dialog_content = "Ayo ambilkan untukku sekarang.",
  ui_story_5065_50650401_12_dialog_content = "Sangat baik, serahkan padaku!",
  ui_story_5065_50650402_1_dialog_content = "Buku-buku ini jauh lebih berat daripada kelihatannya...",
  ui_story_5065_50650402_2_dialog_content = "Fyuh! Syukurlah aku hampir sampai di perpustakaan! Tinggal sedikit lagi sekarang!",
  ui_story_5065_50650402_3_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5065_50650402_4_dialog_content = "Oh tidak... Maafkan aku!",
  ui_story_5065_50650402_5_dialog_content = "Aku berlari sangat cepat sampai-sampai tidak menyadari kamu di sana... Apakah kamu baik-baik saja?",
  ui_story_5065_50650402_6_dialog_content = "(Itulah kata-kataku saat pertama kali bertemu dengan Pam. Aku ingin tahu apakah dia masih ingat.)",
  ui_story_5065_50650402_7_dialog_content = "Oh...",
  ui_story_5065_50650402_8_dialog_content = "A-Aku baik-baik saja. Tolong jangan menyalahkan dirimu sendiri, lady ksatria.",
  ui_story_5065_50650402_9_dialog_content = "(Pam juga mengatakan hal yang sama persis saat itu!)",
  ui_story_5065_50650402_10_dialog_content = "Saya juga terburu-buru, dan gagal memperhatikan sekitar saya...",
  ui_story_5065_50650402_11_dialog_content = "Jika ada yang harus meminta maaf, seharusnya itu aku!",
  ui_story_5065_50650402_12_dialog_content = "(Cara dia menatapku... Seperti dia melihat orang asing sepenuhnya.)",
  ui_story_5065_50650402_13_dialog_content = "Kamu benar-benar tidak ingat siapa aku?",
  ui_story_5065_50650402_14_dialog_content = "Er... Dari pakaianmu, bolehkah aku berasumsi bahwa kamu adalah seorang Ksatria Keadilan?",
  ui_story_5065_50650402_15_dialog_content = "Ada sesuatu tentang kamu yang agak familiar, ya. Apakah kita pernah bertemu di Balai Kehakiman sebelumnya?",
  ui_story_5065_50650402_16_dialog_content = "Aku Irridon, orang yang ingin kamu balas dendam... Kamu tidak ingat apa-apa tentang ini?",
  ui_story_5065_50650402_17_dialog_content = "Sejak muda, saya selalu memeluk ajaran God of Light. Saya tidak akan mudah mencari balas dendam terhadap orang lain...",
  ui_story_5065_50650402_18_dialog_content = "Berhenti larut dalam fantasi ini! Semuanya bohong, sekarang bangun!!",
  ui_story_5065_50650402_19_dialog_content = "Apakah... Apakah kamu yakin kamu tidak salah mengira aku dengan orang lain?",
  ui_story_5065_50650402_20_dialog_content = "Maafkan saya, tetapi saya sedang menjalankan tugas penting. Saya tidak bisa tinggal di sini lebih lama, tetapi saya berdoa agar Anda menemukan orang yang Anda cari.",
  ui_story_5065_50650403_1_dialog_content = "Tidak, seharusnya aku yang minta maaf. Aku menjatuhkan buku-buku dari tanganmu, jadi setidaknya biarkan aku membantumu mengambilnya.",
  ui_story_5065_50650403_2_dialog_content = "Tidak apa-apa, saya bisa mengumpulkannya sendiri dengan cukup cepat!",
  ui_story_5065_50650403_3_dialog_content = "Siapapun yang kamu cari pasti sangat penting bagimu, ya? Tolong jangan tunda pencarianmu karena saya.",
  ui_story_5065_50650403_4_dialog_content = "...",
  ui_story_5065_50650404_1_dialog_content = "Huh, siapa yang meninggalkan semua potongan kertas ini berserakan di halaman kampus? Jika tidak ada yang akan membersihkannya, sepertinya tugas itu jatuh kepadaku...",
  ui_story_5065_50650404_2_dialog_content = "Pam...",
  ui_story_5065_50650404_3_dialog_content = "Wanita Irridon?",
  ui_story_5065_50650404_4_dialog_content = "Akhirnya kamu ingat aku?!",
  ui_story_5065_50650404_5_dialog_content = "... Kau baru saja memperkenalkan diri kepadaku beberapa menit yang lalu.",
  ui_story_5065_50650404_6_dialog_content = "Pekerjaan seorang Justice Knight pasti menghabiskan sebagian besar waktu mereka, bukan? Mengapa kamu mengikutiku selama ini?",
  ui_story_5065_50650404_7_dialog_content = "Aku... Aku belum benar-benar meminta maaf karena menabrakmu tadi.",
  ui_story_5065_50650404_8_dialog_content = "Aku ingin membantu kamu... Jika bukan dengan membersihkan kekacauan ini, setidaknya dengan mengembalikan bukumu untukmu. Apakah itu baik-baik saja?",
  ui_story_5065_50650404_9_dialog_content = "Aku tidak mungkin menyusahkanmu dengan sesuatu yang sepele seperti membersihkan, tapi jika kamu tetap ingin membantu...",
  ui_story_5065_50650404_10_dialog_content = "Bisakah aku minta kamu mengembalikan buku-buku ini, lalu memeriksa salinan yang berbeda untuk masing-masing buku lagi?",
  ui_story_5065_50650404_11_dialog_content = "Ya, tentu saja!",
  ui_story_5065_50650405_1_dialog_content = "Ini buku-buku yang kamu minta, Pam.",
  ui_story_5065_50650405_2_dialog_content = "Terima kasih, Lady Irridon!",
  ui_story_5065_50650405_3_dialog_content = "Hmm? \"Mimpi dan Kenyataan,\" \"Kebangkitan,\" \"Cara Menghindari Menjadi Korban Mimpi Anda\"...?",
  ui_story_5065_50650405_4_dialog_content = "Ini jelas bukan buku yang saya minta!",
  ui_story_5065_50650405_5_dialog_content = "Pam, tolong! Dunia di sekitar kita bukan dunia nyata, ini hanya mimpi! Mimpi kamu!",
  ui_story_5065_50650405_6_dialog_content = "Jika kita tetap terperangkap di sini... Diriku yang sebenarnya akan perlahan kehilangan akal sehat hingga kita semua mati!",
  ui_story_5065_50650405_7_dialog_content = "Berhentilah membohongi diri sendiri! Buka matamu dan lihat dunia ini apa adanya!",
  ui_story_5065_50650405_8_dialog_content = "Apa sebenarnya yang kamu inginkan dariku? Sejak kita bertemu, kamu tidak pernah berhenti mengatakan hal-hal aneh.",
  ui_story_5065_50650405_9_dialog_content = "Aku tidak mengerti kata-katamu, dan juga tidak ingin...",
  ui_story_5065_50650405_10_dialog_content = "Sekarang jika Anda memaafkan saya, saya memiliki urusan mendesak yang harus dihadiri. Urusan yang sangat penting bagi saya juga.",
  ui_story_5065_50650405_11_dialog_content = "Demi nama Dewa Cahaya, aku meminta agar kau tidak menggangguku lagi. Demi White Night, dan selamat siang untukmu.",
  ui_story_5065_50650405_12_dialog_content = "Tapi tugas-tugas ini sama sekali tak ada artinya untukmu, Pam!",
  ui_story_5065_50650405_13_dialog_content = "Wanita Irridon, aku bisa tahu hanya dengan melihat bahwa kamu berasal dari keluarga bangsawan, jadi mungkin kamu tidak mengerti...",
  ui_story_5065_50650405_14_dialog_content = "Namun, menjadi seorang inisiat sangat sulit bagiku. Jika aku ingin mewujudkan mimpiku, aku harus menyelesaikan tugas-tugas ini dengan sempurna dan sebaik mungkin.",
  ui_story_5065_50650405_15_dialog_content = "Bagaimana mungkin kamu bisa mengklaim bahwa semua ini tidak ada artinya bagi saya?",
  ui_story_5065_50650405_16_dialog_content = "Kalau kamu benar-benar berniat menghentikanku... L-Lalu aku tidak punya pilihan selain bersikap lebih tegas!",
  ui_story_5065_50650406_1_dialog_content = "Maafkan saya, Yang Mulia... Saya menghadapi beberapa kendala saat menjalankan tugas-tugas saya.",
  ui_story_5065_50650406_2_dialog_content = "Sebenarnya, aku bisa mengembalikan bukumu lebih cepat.",
  ui_story_5065_50650406_3_dialog_content = "Tidak apa-apa; aku juga tidak akan membacanya...",
  ui_story_5065_50650406_4_dialog_content = "Maksudku, aku tidak terburu-buru untuk membaca mereka.",
  ui_story_5065_50650406_5_dialog_content = "Oh, begitu…",
  ui_story_5065_50650501_1_dialog_content = "Selamat pagi, Yang Mulia!",
  ui_story_5065_50650501_2_dialog_content = "Pagi!",
  ui_story_5065_50650501_3_dialog_content = "Translation:Apa tugasasan\" untuk saya hari ini, Tuan?",
  ui_story_5065_50650501_4_dialog_content = "Misi? Oh, apakah kamu... apakah kamu telah membantu saya menangkap pencuri-pencuri itu baru-baru ini?",
  ui_story_5065_50650501_5_dialog_content = "Ya, Pak! Mendapatkan kepercayaan Anda pada hari pertama saya sebagai trainee dan membantu Anda menyelesaikan kasus penting seperti ini merupakan kehormatan besar bagi saya!",
  ui_story_5065_50650501_6_dialog_content = "Haha, kamu sangat membantu. Berkat kamu, pekerjaanku berjalan lancar akhir-akhir ini.",
  ui_story_5065_50650501_7_dialog_content = "Apakah pencuri-pencuri itu memiliki kaki tangan lain yang masih berkeliaran?",
  ui_story_5065_50650501_8_dialog_content = "Kaki tangan lainnya? Saya tidak berpikir begitu. Jangan repot-repot memikirkannya.",
  ui_story_5065_50650501_9_dialog_content = "Lagi pula, tidak banyak yang terjadi di sini sekarang. Kamu bisa kembali. Terima kasih untuk hari-hari ini.",
  ui_story_5065_50650501_10_dialog_content = "Er, tapi Yang Mulia...",
  ui_story_5065_50650501_11_dialog_content = "Apakah ada sesuatu yang lain?",
  ui_story_5065_50650501_12_dialog_content = "T-Tidak pak, saya hanya menyadari bahwa Anda terlihat lebih baik hati dari biasanya hari ini.",
  ui_story_5065_50650501_13_dialog_content = "Tapi sekarang akhirnya aku mengerti! Selama beberapa hari ini, kau hanya memerankan instruktur yang keras!",
  ui_story_5065_50650501_14_dialog_content = "Karena hanya instruktur yang keras yang dapat menghasilkan siswa yang luar biasa! Terima kasih banyak telah membimbing saya dengan baik...",
  ui_story_5065_50650501_15_dialog_content = "Hah? T-tidak perlu berterima kasih padaku, hahaha...",
  ui_story_5065_50650501_16_dialog_content = "Meskipun singkat, saya akan selalu menghargai waktu yang saya habiskan bekerja di bawah bimbingan Anda, Hakim Junior!",
  ui_story_5065_50650502_1_dialog_content = "Selamat siang, instruktur!",
  ui_story_5065_50650502_2_dialog_content = "Pam? Bukankah kamu seharusnya berada di Hall of Justice sekarang?",
  ui_story_5065_50650502_3_dialog_content = "Saya telah menyelesaikan tugas-tugas awal yang diberikan kepada saya oleh Hall of Justice, jadi Hakim Junior mengizinkan saya untuk kembali lebih cepat.",
  ui_story_5065_50650502_4_dialog_content = "Hakim Junior, begitukah?",
  ui_story_5065_50650502_5_dialog_content = "Hmm?",
  ui_story_5065_50650502_6_dialog_content = "(Apa yang dilakukan Hakim Junior di sini juga?)",
  ui_story_5065_50650502_7_dialog_content = "(Ahhh... Aku begitu emosional saat kita berpisah tadi, jadi bertemu dengannya lagi begitu cepat terasa sedikit canggung.)",
  ui_story_5065_50650502_8_dialog_content = "Aku tidak pernah memberitahu Pam bahwa quest sudah selesai, kan?",
  ui_story_5065_50650502_9_dialog_content = "Hah? Tapi di Hall of Justice tadi, kamu bilang...",
  ui_story_5065_50650502_10_dialog_content = "Aku bahkan tidak pergi ke Hall of Justice hari ini! Oh, aku tahu apa yang terjadi di sini; kamu mencoba untuk bolos kerja, bukan?",
  ui_story_5065_50650502_11_dialog_content = "Dan di sinilah saya, datang untuk bertemu mentor Anda, berharap untuk memperpanjang waktu Anda sebagai peserta pelatihan di Hall of Justice.",
  ui_story_5065_50650502_12_dialog_content = "Ya ampun, kamu benar-benar tidak bisa menilai orang dari penampilan mereka saat ini, terutama yang muda-muda.",
  ui_story_5065_50650502_13_dialog_content = "Sepertinya saya harus mengejar pemimpin geng pencuri secara pribadi.",
  ui_story_5065_50650502_14_dialog_content = "A-Apa yang kau katakan?!",
  ui_story_5065_50650502_15_dialog_content = "Lalu orang yang saya ajak bicara di Balai Kehakiman...",
  ui_story_5065_50650502_16_dialog_content = "Oh tidak!!!",
  ui_story_5065_50650502_17_dialog_content = "Kita perlu kembali dan hentikan pria itu!",
  ui_story_5065_50650503_1_dialog_content = "Penjaga, di mana pencuri yang kita tangkap beberapa hari yang lalu ditahan?",
  ui_story_5065_50650503_2_dialog_content = "Apakah kamu berencana menginterogasi mereka? Silakan ikut denganku.",
  ui_story_5065_50650503_3_dialog_content = "Tunggu!",
  ui_story_5065_50650503_4_dialog_content = "Kamu lagi? Kenapa kembali ke sini?",
  ui_story_5065_50650503_5_dialog_content = "Kamu tidak akan menginterogasi para pencuri itu! Kamu akan membebaskan mereka, bukan?!",
  ui_story_5065_50650503_6_dialog_content = "Kamu... Kamu punya nyali! Hanya seorang pemula, dan berani-beraninya kamu menanyakan hal itu padaku?",
  ui_story_5065_50650503_7_dialog_content = "Karena aku tidak datang ke sini sendirian.",
  ui_story_5065_50650503_8_dialog_content = "Apa?",
  ui_story_5065_50650503_9_dialog_content = "Meniru anggota penting dari Balai Kehakiman, Anda menambahkan tuduhan lain ke daftar Anda.",
  ui_story_5065_50650503_10_dialog_content = "!!!",
  ui_story_5065_50650503_11_dialog_content = "Penjaga, tangkap pencuri di depan kamu!",
  ui_story_5065_50650503_12_dialog_content = "Demi White Night, aku tak percaya pencuri-pencuri ini begitu licik...",
  ui_story_5065_50650503_13_dialog_content = "Semua berkat kamu, saya bisa menyelesaikan kasus ini dengan lancar.",
  ui_story_5065_50650503_14_dialog_content = "Aku ingin kamu tinggal lebih lama di Hall of Justice, tapi mentormu sangat menentangnya.",
  ui_story_5065_50650503_15_dialog_content = "Aku sudah merindukan hari-hari saat kamu bekerja untukku...",
  ui_story_5065_50650503_16_dialog_content = "Huff... Tetap semangat! Jika Anda mendapatkan kesempatan, pastikan untuk melamar posisi di Hall of Justice!",
  ui_story_5065_50650503_17_dialog_content = "Terima kasih banyak telah percaya padaku, Yang Mulia. Saya pasti akan kembali dan menjumpai Anda suatu hari nanti!",
  ui_story_5065_50650601_1_dialog_content = "Pam, saya sudah mendengar sedikit tentang penampilan Anda di Balai Kehakiman dari Hakim Junior.",
  ui_story_5065_50650601_2_dialog_content = "Hakim Junior ingin Anda tinggal bersamanya beberapa hari lagi, tetapi jangan khawatir, saya menolak permintaannya.",
  ui_story_5065_50650601_3_dialog_content = "Sebagai seorang trainee, tugas utama kamu sekarang adalah untuk mengenal seluk-beluk afiliasi di bawah Kuil Lumopolis; itulah tujuan dari rotasi peran yang kamu jalani.",
  ui_story_5065_50650601_4_dialog_content = "Pernahkah Anda berpikir tentang di mana Anda ingin melakukan pelatihan berikutnya?",
  ui_story_5065_50650601_5_dialog_content = "Saya belum memikirkannya karena selama ini hanya mengikuti perintah Anda.",
  ui_story_5065_50650601_6_dialog_content = "Tapi jika diberi pilihan, tempat yang paling ingin aku pelajari jelas—di dalam Lumopolis Temple!",
  ui_story_5065_50650601_7_dialog_content = "Pernahkah kamu mendengar tentang Divisi Investigasi yang berada di bawah perintah langsung Kuil Lumopolis?",
  ui_story_5065_50650601_8_dialog_content = "Apakah kamu maksud kelompok yang melindungi dan menguatkan iman orang-orang pada Dewa Cahaya?",
  ui_story_5065_50650601_9_dialog_content = "Kudengar hanya siswa terbaik yang bisa bergabung dengan Divisi Penyelidikan. Aku juga dengar... bahwa kamu salah satunya.",
  ui_story_5065_50650601_10_dialog_content = "Kamu cukup tahu banyak, harus kuakui.",
  ui_story_5065_50650601_11_dialog_content = "Saat ini, Anda memiliki kesempatan untuk membantu Divisi Investigasi. Apakah Anda bersedia mencobanya?",
  ui_story_5065_50650601_12_dialog_content = "T-Tentu saja! Tapi... apakah seseorang seperti saya benar-benar layak bergabung dengan Divisi Investigasi?",
  ui_story_5065_50650601_13_dialog_content = "Divisi Investigasi akhir-akhir ini sangat membutuhkan tenaga kerja. Jika Anda unggul selama fase dukungan, Anda mungkin akan menjadi anggota resmi di masa depan.",
  ui_story_5065_50650601_14_dialog_content = "Tetapi saya harus memperingatkan Anda, tugas-tugas Divisi Investigasi jauh lebih berbahaya daripada tugas-tugas di Hall of Justice.",
  ui_story_5065_50650601_15_dialog_content = "Dengan bahaya yang lebih besar datang kepercayaan dan kehormatan yang lebih besar. Saya bersedia menerima risikonya!",
  ui_story_5065_50650601_16_dialog_content = "Senang mendengarnya. Akhir-akhir ini, ada laporan tentang anggota True Order yang mempromosikan keyakinan mencurigakan menyusup ke Lumopolis.",
  ui_story_5065_50650601_17_dialog_content = "Kehadiran mereka merupakan ancaman serius bagi keyakinan dan kesejahteraan warga Lumopolis.",
  ui_story_5065_50650601_18_dialog_content = "Ada informasi yang menunjukkan bahwa beberapa dari mereka telah menyelinap ke Dawn Academy. Aku membutuhkan bantuanmu untuk mengungkap identitas mereka. Bisakah kamu menangani tugas ini?",
  ui_story_5065_50650601_19_dialog_content = "Demi White Night! Aku tak akan berhenti sampai aku mengusir mereka semua dari kota suci dan murni kita!",
  ui_story_5065_50650602_1_dialog_content = "Di hadapan Kebenaran, Anda dan saya hanyalah debu yang tak berarti.",
  ui_story_5065_50650602_2_dialog_content = "Kita harus bertobat karena gagal memahami kebenaran tepat waktu dan karena mencoba untuk memahaminya.",
  ui_story_5065_50650602_3_dialog_content = "...",
  ui_story_5065_50650602_4_dialog_content = "Halo. Apakah Anda datang untuk belajar tentang True Order?",
  ui_story_5065_50650602_5_dialog_content = "Demi White Night, kamu harusnya malu pada dirimu sendiri!",
  ui_story_5065_50650603_1_dialog_content = "Kerja bagus mengusir penyusup dari Dawn Academy dengan cepat! Mengesankan!",
  ui_story_5065_50650603_2_dialog_content = "Tidak umum bagi seseorang untuk mencapai hasil seperti itu dalam tugas solo pertama mereka, bahkan di dalam Lumopolis Temple.",
  ui_story_5065_50650603_3_dialog_content = "Namun situasi saat ini jauh dari optimis. Kabarnya mereka juga berhasil menyusup ke Balai Kehakiman.",
  ui_story_5065_50650603_4_dialog_content = "Mengingat pengalaman Anda sebelumnya di Hall of Justice, Anda seharusnya tahu jalan di sekitar sana.",
  ui_story_5065_50650603_5_dialog_content = "Selanjutnya, aku ingin kamu pergi lagi ke Hall of Justice.",
  ui_story_5065_50650604_1_dialog_content = "Keindahan bangunan ini hanya bertujuan untuk menyembunyikan kekurangannya.",
  ui_story_5065_50650604_2_dialog_content = "Mirip seperti hukum yang mengatur Lumopolis, kemegahan mereka hanya menyembunyikan banyak celah yang tersembunyi di dalamnya.",
  ui_story_5065_50650604_3_dialog_content = "... Bukankah kamu juga memakai duri-duri itu untuk menunjukkan betapa kuatnya kamu kepada orang lain?",
  ui_story_5065_50650604_4_dialog_content = "Demi White Night di atas, aku bersumpah untuk menemukan pemilik yang lebih pantas untuk duri-duri ini!",
  ui_story_5065_50650701_1_dialog_content = "Pam, apa yang membawamu ke sini hari ini? Apakah kamu lupa sesuatu?",
  ui_story_5065_50650701_2_dialog_content = "Hari ini adalah hari libur.",
  ui_story_5065_50650701_3_dialog_content = "Tapi pekerjaan kita akhir-akhir ini sangat mendesak...",
  ui_story_5065_50650701_4_dialog_content = "Saya tahu saat ini situasinya cukup sulit, tetapi sebagai seorang trainee, Anda tidak perlu memaksakan diri terlalu keras untuk saat ini.",
  ui_story_5065_50650701_5_dialog_content = "Tahu kan, di masa depan nanti kamu akan menghadapi banyak hari sibuk.",
  ui_story_5065_50650701_6_dialog_content = "Oh...",
  ui_story_5065_50650701_7_dialog_content = "Jadi, jangan stres sekarang.",
  ui_story_5065_50650701_8_dialog_content = "S-Sama sekali tidak! Saya sangat bahagia untuk mengabdikan setiap hari dalam hidup saya bekerja untuk Kuil Lumopolis!",
  ui_story_5065_50650701_9_dialog_content = "Anda telah mengalami banyak hal belakangan ini. Manfaatkan hari libur ini dan luangkan waktu bersama keluarga.",
  ui_story_5065_50650702_1_dialog_content = "Pam!",
  ui_story_5065_50650702_2_dialog_content = "Wanita Irridon...? Ada apa sekarang?",
  ui_story_5065_50650702_3_dialog_content = "Saat menjalankan perintahku, aku terlibat dengan sekelompok pengawal yang aneh...",
  ui_story_5065_50650702_4_dialog_content = "Demi White Night, pertengkaran apa yang mereka miliki dengan seorang Ksatria Keadilan?",
  ui_story_5065_50650702_5_dialog_content = "Jangan bilang kamu juga memprovokasi mereka dengan salah mengenali identitas mereka?",
  ui_story_5065_50650702_6_dialog_content = "Mereka sama sekali bukan Penjaga Lumo! Lihat sendiri!",
  ui_story_5065_50650702_7_dialog_content = "Perlindungan! Kesetiaan! Kemuliaan!",
  ui_story_5065_50650702_8_dialog_content = "Hah? Kamu benar, ada sesuatu yang aneh dengan para pengawal ini!",
  ui_story_5065_50650702_9_dialog_content = "Menyerang!",
  ui_story_5065_50650702_10_dialog_content = "Para penjaga itu... Bagaimana mereka bisa menghilang begitu saja?",
  ui_story_5065_50650702_11_dialog_content = "Cukup aneh, bukan?",
  ui_story_5065_50650702_12_dialog_content = "Sekarang saya kira kamu akan memberi tahu saya bahwa ini hanya bisa terjadi karena kita berada di dunia mimpi, ya?",
  ui_story_5065_50650702_13_dialog_content = "Syukurlah kamu akhirnya mulai percaya padaku, Pam!",
  ui_story_5065_50650702_14_dialog_content = "... Aku tidak percaya padamu. Ini pasti semacam trik yang mereka pelajari di suatu tempat.",
  ui_story_5065_50650702_15_dialog_content = "Dalam hal ini, saya akan melaporkan masalah ini ke Lumopolis Temple.",
  ui_story_5065_50650702_16_dialog_content = "...",
  ui_story_5065_50650702_17_dialog_content = "Jika Anda memaafkan saya, Lady Irridon, saya perlu mengunjungi kakek saya sekarang. Selamat siang.",
  ui_story_5065_50650702_18_dialog_content = "Pam...",
  ui_story_5065_50650703_1_dialog_content = "Mengapa kakek belum mengatur seseorang untuk membersihkan daun-daun di depan rumahnya?",
  ui_story_5065_50650703_2_dialog_content = "Biar aku membantu menyapu mereka.",
  ui_story_5065_50650703_3_dialog_content = "Kau... Apakah kau mengikuti aku lagi?!",
  ui_story_5065_50650703_4_dialog_content = "Aku di sini untuk urusan keluarga, jadi bantuan Justice Knight tidak diperlukan.",
  ui_story_5065_50650703_5_dialog_content = "Sekarang tolong urus saja urusanmu sendiri!",
  ui_story_5065_50650704_1_dialog_content = "...",
  ui_story_5065_50650704_2_dialog_content = "Mengapa kamu masih di sini, Wanita Irridon?",
  ui_story_5065_50650704_3_dialog_content = "Jika kamu terus mencoba meyakinkan saya bahwa dunia ini hanyalah mimpi, saya tidak punya pilihan selain mencurigai kamu sebagai anggota True Order.",
  ui_story_5065_50650704_4_dialog_content = "Aku... Aku tak akan mengganggumu lagi dengan membahas hal itu.",
  ui_story_5065_50650704_5_dialog_content = "Sebenarnya, aku membeli beberapa bahan untuk membuat makanan, tapi aku tidak tahu cara menyiapkannya.",
  ui_story_5065_50650704_6_dialog_content = "Aku dengar kamu masaknya hebat, jadi aku ingin minta bantuanmu.",
  ui_story_5065_50650704_7_dialog_content = " a good translation of the text from English to unraveled or 201 TABLES: The text is a translation of the text from English to Indonesian.",
  ui_story_5065_50650704_8_dialog_content = "... Iya.",
  ui_story_5065_50650704_9_dialog_content = "Hahaha, kalau begitu kamu datang ke orang yang tepat! Sini, biar aku lihat apa yang kamu beli!",
  ui_story_5065_50650704_10_dialog_content = "Hanya sedikit tepung dan beberapa kacang.",
  ui_story_5065_50650704_11_dialog_content = "Tepung ini tampak pudar dan kusam, kacangnya mengkerut... Apakah Anda yakin Anda tidak ditipu oleh orang yang menjualnya kepada Anda?",
  ui_story_5065_50650704_12_dialog_content = "Saya dengar banyak orang di Lumopolis Bawah hanya mampu membeli bahan seperti ini, jadi saya ingin mencobanya juga.",
  ui_story_5065_50650704_13_dialog_content = "Apakah ini yang sedang tren di kalangan bangsawan saat ini?",
  ui_story_5065_50650704_14_dialog_content = "Aku hanya ingin memiliki gambaran yang lebih jelas tentang bagaimana kehidupan orang-orang lain di Lumopolis.",
  ui_story_5065_50650704_15_dialog_content = "Jika saya bisa menemukan cara untuk mengubah bahan-bahan ini menjadi sesuatu yang lezat, saya bisa berbagi resepnya dengan semua orang.",
  ui_story_5065_50650704_16_dialog_content = "... Saya tidak tahu kamu memiliki sisi ini, Lady Irridon.",
  ui_story_5065_50650704_17_dialog_content = "Dengan perhatian dan dedikasi yang cukup, kamu bisa membuat makanan lezat dari bahan apa pun. Tunggu sebentar, ya!",
  ui_story_5065_50650704_18_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian...</color>",
  ui_story_5065_50650704_19_dialog_content = "Maaf membuatmu menunggu! Ini, coba saja!",
  ui_story_5065_50650704_20_dialog_content = "Rasa ini... Rasanya persis sama...",
  ui_story_5065_50650704_21_dialog_content = "Rasanya persis seperti saat pertama kali kumakan!",
  ui_story_5065_50650704_22_dialog_content = "Benar-benar? Kebetulan yang aneh. Siapa yang membuatnya untuk kamu waktu itu?",
  ui_story_5065_50650704_23_dialog_content = "Bahkan setelah membuat ini, kamu masih tidak ingat apa-apa, ya Pam?",
  ui_story_5065_50650704_24_dialog_content = "Sudah kuduga. Kamu sama sekali tidak berniat belajar resep baru dariku, Lady Irridon.",
  ui_story_5065_50650704_25_dialog_content = "Aku masih perlu menemui kakekku, jadi maafkan aku sudah memintamu untuk pergi begitu cepat. Dan juga...",
  ui_story_5065_50650704_26_dialog_content = "Anda harus meluangkan waktu untuk menemui dokter, Lady Irridon. Saya sangat khawatir tentang kesehatan mental Anda.",
  ui_story_5065_50650704_27_dialog_content = "Huh...",
  ui_story_5065_50650704_28_dialog_content = "Aku gagal lagi.",
  ui_story_5065_50650704_29_dialog_content = "Kamu belum gagal... Kita masih punya kesempatan lain!",
  ui_story_5065_50650704_30_dialog_content = "Jangan menyerah saja!!!",
  ui_story_5065_50650704_31_dialog_content = "... Kau benar. Aku tak bisa menyerah begitu saja.",
  ui_story_5065_50650704_32_dialog_content = "Akhirnya saya mengerti betapa sulitnya bagi kamu untuk membangunkanku...",
  ui_story_5065_50650704_33_dialog_content = "Tapi jangan khawatir, aku lebih dari mampu melakukannya sekar to be more than capable of doing this now.",
  ui_story_5065_50650801_1_dialog_content = "Selamat pagi, instruktur!",
  ui_story_5065_50650801_2_dialog_content = "Pam, sudah merasa lebih baik setelah istirahat?",
  ui_story_5065_50650801_3_dialog_content = "Saya merasa sangat istirahat, terima kasih sudah menanyakan. Saya juga menantikan untuk memulai tugas berikutnya!",
  ui_story_5065_50650801_4_dialog_content = "Terima kasih atas bantuanmu selama ini, kami berhasil membersihkan semua penyusup True Order dari Taman Lumopolis.",
  ui_story_5065_50650801_5_dialog_content = "Namun masih ada tanda-tanda aktivitas mereka di luar Taman Lumopolis. Kita perlu menjaga momentum dan terus mengejar mereka.",
  ui_story_5065_50650801_6_dialog_content = "Mengerti. Saya akan pastikan mengusir mereka semua sampai tak bersisa!",
  ui_story_5065_50650801_7_dialog_content = "Mereka pandai bersembunyi, jadi kami membutuhkan kamu untuk berpatroli dan selalu waspada.",
  ui_story_5065_50650801_8_dialog_content = "Paham!",
  ui_story_5065_50650802_1_dialog_content = "Ingin tahu rahasia di balik mata kananku?",
  ui_story_5065_50650802_2_dialog_content = "Aku janji, bergabunglah dengan kami di True Order, dan kamu akan menemukan lebih banyak lagi rahasia.",
  ui_story_5065_50650802_3_dialog_content = "... Tentang mata kananku, atau ajaran kotor dari kota ini.",
  ui_story_5065_50650802_4_dialog_content = "Lumopolis adalah kota yang suci yang tidak akan pernah jatuh. Bagaimana mungkin ada ajaran kotor seperti yang kamu klaim?!",
  ui_story_5065_50650802_5_dialog_content = "Omonganmu tidak lebih dari ajaran sesat yang samar dan membingungkan!",
  ui_story_5065_50650803_1_dialog_content = "Kerja bagus, Pam!",
  ui_story_5065_50650803_2_dialog_content = "Jalanan di Halaman Lumopolis kembali bersih dan tenang, semua berkat kamu.",
  ui_story_5065_50650803_3_dialog_content = "Tetapi para penjahat itu telah memanfaatkan kesempatan untuk melarikan diri ke Lower Lumopolis.",
  ui_story_5065_50650803_4_dialog_content = "Populasi di distrik itu adalah campuran yang beragam dari berbagai orang, dan iman para penduduk tidak cukup kuat, yang membuatnya menjadi fokus utama kita.",
  ui_story_5065_50650803_5_dialog_content = "Para senior dari Divisi Investigasi sudah melakukan pengejaran di Lower Lumopolis. Kamu harus pergi dan membantu mereka.",
  ui_story_5065_50650803_6_dialog_content = "Saya akan senang bekerja bersama atasan saya!",
  ui_story_5065_50650804_1_dialog_content = "...",
  ui_story_5065_50650804_2_dialog_content = "Mengapa kamu menggigil di pojok, Nona? Apakah kamu merasa tidak sehat?",
  ui_story_5065_50650804_3_dialog_content = "A... Aku baik-baik saja. Hanya saja, aku tidak tahu cara menyelesaikan tugas yang mereka berikan padaku...",
  ui_story_5065_50650804_4_dialog_content = "Mereka baik padaku, dan aku benar-benar ingin membantu mereka... Tapi aku terlalu tidak berguna.",
  ui_story_5065_50650804_5_dialog_content = "Apa tugas kamu? Mungkin aku bisa membantu?",
  ui_story_5065_50650804_6_dialog_content = "Tujuannya... untuk meyakinkan semua orang agar bergabung dengan True Order.",
  ui_story_5065_50650804_7_dialog_content = "Apa?!",
  ui_story_5065_50650804_8_dialog_content = "Maafkan aku telah memperlakukanmu dengan tidak baik... Tapi aku tidak punya pilihan lain.",
  ui_story_5065_50650901_1_dialog_content = "Pam, ini dia.",
  ui_story_5065_50650901_2_dialog_content = "Ya. Apakah Anda punya tugas lain untuk saya?",
  ui_story_5065_50650901_3_dialog_content = "Bukan aku; ada seorang guru dari Akademi Dawn yang mencarimu. Dia ingin kamu kembali ke sekolah dan membantu.",
  ui_story_5065_50650901_4_dialog_content = "Dia mencari saya? Aku ingin tahu kenapa...?",
  ui_story_5065_50650901_5_dialog_content = "Sepertinya ini ada hubungannya dengan penelitian terbarunya.",
  ui_story_5065_50650901_6_dialog_content = "Terima kasih. Aku akan kembali ke Akademi segera!",
  ui_story_5065_50650902_1_dialog_content = "Halo, Pak. Apakah Anda membutuhkan bantuan saya untuk sesuatu?",
  ui_story_5065_50650902_2_dialog_content = "Pam, bagus sekali kamu kembali!",
  ui_story_5065_50650902_3_dialog_content = "Mungkin kamu pernah mendengar bahwa saya sedang melakukan penelitian tentang \"berat objek pada ketinggian yang berbeda.",
  ui_story_5065_50650902_4_dialog_content = "Saya percaya bahwa suatu benda lebih ringan di Lumopolis Gardens daripada di Lower Lumopolis.",
  ui_story_5065_50650902_5_dialog_content = "Belakangan ini, penelitian saya telah memasuki tahap empiris terakhir.",
  ui_story_5065_50650902_6_dialog_content = "Jika hipotesis ini dapat dibuktikan benar, ini akan memicu gelombang revolusi di komunitas akademik Lumopolis!",
  ui_story_5065_50650902_7_dialog_content = "Apa kamu tahu kenapa?",
  ui_story_5065_50650902_8_dialog_content = "A-aku tidak bisa bilang aku tahu, tapi tolong jelaskan!",
  ui_story_5065_50650902_9_dialog_content = "Karena begitu hipotesis ini terbukti, hal tersebut akan menunjukkan bahwa Dewa Cahaya telah mengambil beban yang signifikan dari Taman Lumopolis!",
  ui_story_5065_50650902_10_dialog_content = "Yang berarti Taman Lumopolis lebih disukai oleh Dewa Cahaya, dan warga di sini seharusnya menerima penghargaan dan dukungan yang lebih besar dari masyarakat!",
  ui_story_5065_50650902_11_dialog_content = "Dengan kata lain, selama kita berdoa dengan tulus, Dewa Cahaya pasti akan memperhatikan...",
  ui_story_5065_50650902_12_dialog_content = "Tapi tanpa prestasi akademik yang bisa dibanggakan, bagaimana mungkin saya bisa membantu Anda?",
  ui_story_5065_50650902_13_dialog_content = "Sebagai seorang trainee, kamu memiliki akses ke patung skala di Lumopolis.",
  ui_story_5065_50650902_14_dialog_content = "Saya ingin kamu pergi ke pintu masuk Hall of Justice, Halaman Lumopolis, dan Lumopolis bagian bawah, lalu mengukur berat dari beban emas ini secara terpisah.",
  ui_story_5065_50650902_15_dialog_content = "Tidak boleh ada pemalsuan atau kecurangan. Apakah kamu mengerti maksudku?",
  ui_story_5065_50650902_16_dialog_content = "Saya mengerti, profesor. Jika pengukuran menunjukkan bahwa pemberat emas paling berat di Lumopolis Bawah, maka itu mengkonfirmasi hipotesis Anda!",
  ui_story_5065_50650902_17_dialog_content = "Betapa mulianya pencapaian ini membuktikan keberadaan berkat-berkat dari Dewa Cahaya...",
  ui_story_5065_50650902_18_dialog_content = "Terima kasih telah mengizinkan saya menjadi bagian dari eksperimen ini, profesor! Saya akan memberikan yang terbaik!",
  ui_story_5065_50650903_1_dialog_content = "Jadi satu-satunya cara untuk mengumpulkan pengukuran ini adalah dengan menyelesaikan Quest of Scales...",
  ui_story_5065_50650903_2_dialog_content = "Tapi tidak apa-apa! Saya pernah menyelesaikan quest serupa sebelumnya, jadi yang ini seharusnya tidak menjadi masalah!",
  ui_story_5065_50650903_3_dialog_content = "Satu timbangan emas setara dengan... tiga timbangan perak.",
  ui_story_5065_50650903_4_dialog_content = "Bagus! Saya harus mencatat semua temuan saya dengan jelas!",
  ui_story_5065_50650904_1_dialog_content = "Hmm, satu pemberat emas sama dengan... Tiga pemberat perak lagi?",
  ui_story_5065_50650904_2_dialog_content = "Ini kemungkinan karena perbedaan ketinggian antara Lumopolis Gardens dan Lumopolis Courtyard cukup kecil...",
  ui_story_5065_50650905_1_dialog_content = "Bagaimana ini mungkin...?",
  ui_story_5065_50650905_2_dialog_content = "Berat emas sama dengan tiga berat perak, tidak peduli ke mana pun saya pergi!!",
  ui_story_5065_50650905_3_dialog_content = "Apa mungkin aku mengukur dengan salah?",
  ui_story_5065_50650905_4_dialog_content = "T-Tidak mungkin, aku mengikuti instruksi untuk timbangan dengan sempurna. Tidak mungkin ada kesalahan...",
  ui_story_5065_50650905_5_dialog_content = "Aku hanya perlu melaporkan temuan ini kepada profesor.",
  ui_story_5065_50650906_1_dialog_content = "Apa?!",
  ui_story_5065_50650906_2_dialog_content = "Tidak mungkin! Bagaimana bisa hasil dari ketiga pengukuran itu sama?!",
  ui_story_5065_50650906_3_dialog_content = "Apakah mungkin teori saya salah? Atau bisa jadi ada masalah dengan subjek eksperimen yang saya pilih? Atau mungkin...",
  ui_story_5065_50650906_4_dialog_content = "Mungkin staf eksperimen ini tidak diberkati oleh Dewa Cahaya?",
  ui_story_5065_50650906_5_dialog_content = "P-Profesor, saya bisa meyakinkan Anda bahwa saya tidak membuat kesalahan saat mengambil pengukuran itu...",
  ui_story_5065_50650906_6_dialog_content = "Aku tahu, itu bukan salahmu.",
  ui_story_5065_50650906_7_dialog_content = "Saya akan memeriksanya lebih dekat untuk mengetahui langkah mana yang salah. Ketika saya menemukannya, mungkin saya akan membutuhkan bantuan Anda lagi.",
  ui_story_5065_50650906_8_dialog_content = "Anda bisa pulang untuk hari ini.",
  ui_story_5065_50650906_9_dialog_content = "Baiklah, Profesor. Semoga harimu menyenangkan...",
  ui_story_5065_50651001_1_dialog_content = "Apakah ada tugas lain untuk saya, instruktur?",
  ui_story_5065_50651001_2_dialog_content = "Nah, kamu datang tepat pada waktunya.",
  ui_story_5065_50651001_3_dialog_content = "Tidak lama yang lalu, kami mengusir beberapa anggota True Order yang telah menyusup ke Lumopolis Bawah.",
  ui_story_5065_50651001_4_dialog_content = "Tapi ada bukti yang menunjukkan bahwa mereka masih memiliki beberapa anggota yang bersembunyi di sana, melakukan pengajaran ilegal.",
  ui_story_5065_50651001_5_dialog_content = "Seperti yang saya katakan sebelumnya, iman penduduk Lumopolis Bawah sangat rapuh, sehingga membuat mereka mudah menjadi sasaran pengaruh Ordo Sejati.",
  ui_story_5065_50651001_6_dialog_content = "Oleh karena itu, kita harus mengadakan lebih banyak ceramah tentang God of Light di Lumopolis bagian bawah.",
  ui_story_5065_50651001_7_dialog_content = "Saya telah meninjau kinerja Anda di Dawn Academy, jadi saya yakin untuk mengirim Anda ke sana untuk tugas-tugas kuliah yang relevan.",
  ui_story_5065_50651001_8_dialog_content = "Kuliah Anda seharusnya diberikan di alun-alun di Lower Lumopolis.",
  ui_story_5065_50651001_9_dialog_content = "Ini... Ini adalah impianku selama ini! Aku berjanji tidak akan mengecewakanmu!",
  ui_story_5065_50651002_1_dialog_content = "Permisi... Bisakah Anda tunjukkan arah menuju alun-alun di Lower Lumopolis?",
  ui_story_5065_50651002_2_dialog_content = "Wanita terkasih, tempat yang Anda cari ada tepat di bawah kaki Anda!",
  ui_story_5065_50651002_3_dialog_content = "May Saya bertanya apakah Anda memerlukan bantuan?",
  ui_story_5065_50651002_4_dialog_content = "Terima kasih sudah memberi tahu. Saya di sini untuk menyampaikan beberapa khotbah singkat.",
  ui_story_5065_50651002_5_dialog_content = "Ini pertama kalinya aku berbicara di depan publik seperti ini, jadi aku merasa sedikit gugup.",
  ui_story_5065_50651002_6_dialog_content = "Itu sangat normal.",
  ui_story_5065_50651002_7_dialog_content = "Semua orang pasti merasa gugup kadang-kadang, bahkan mereka yang sudah berpengalaman memberikan ribuan pidato sepanjang hidup mereka.",
  ui_story_5065_50651002_8_dialog_content = "Kamu hanya perlu belajar menikmati kegugupanmu. Hargai detak jantung yang meningkat dan keringat yang merangsang di telapak tanganmu.",
  ui_story_5065_50651002_9_dialog_content = "Rangsangan yang sama itu akan membantu kamu menyampaikan pidato yang lebih berdampak.",
  ui_story_5065_50651002_10_dialog_content = "Aku hanya khawatir kalau kata-kataku tidak akan menarik perhatian orang-orang.",
  ui_story_5065_50651002_11_dialog_content = "Tugas yang cukup sederhana. Izinkan saya membantu Anda mengumpulkan audiens.",
  ui_story_5065_50651002_12_dialog_content = "Hah?",
  ui_story_5065_50651002_13_dialog_content = "<color=#e8d9bb>Tak lama kemudian, alun-alun dipenuhi warga dari segala usia, dan Pam mulai mengajar dengan lancar.</color>",
  ui_story_5065_50651002_14_dialog_content = "... Dan dengan itu, inilah kesimpulan dari ajaran yang ingin saya bagikan dengan kamu hari ini.",
  ui_story_5065_50651002_15_dialog_content = "Singkatnya, selama hati Anda penuh penyesalan, Dewa Cahaya akan memberkati Anda dengan pengampunan ilahi-Nya!",
  ui_story_5065_50651002_16_dialog_content = "Sayangnya, nasib seseorang tidak bisa diubah melalui keyakinan.",
  ui_story_5065_50651002_17_dialog_content = "Apa yang membuat Anda mengatakan itu, Pak?",
  ui_story_5065_50651002_18_dialog_content = "...",
  ui_story_5065_50651002_19_dialog_content = "Hah? Tunggu... Tolong jangan pergi!",
  ui_story_5065_50651003_1_dialog_content = "Kemana pria tua itu pergi? Saya hanya ingin meminta dia untuk berbagi kisah duka citanya dengan saya...",
  ui_story_5065_50651003_2_dialog_content = "Hadirin sekalian!",
  ui_story_5065_50651003_3_dialog_content = "Hah? Itu orang baik hati dari sebelumnya... Apakah dia juga memberikan pidato di sini?",
  ui_story_5065_50651003_4_dialog_content = "Ada saat-saat di mana ideologi harus bertabrakan agar benar-benar bersinar.",
  ui_story_5065_50651003_5_dialog_content = "Dan saat ini, suara masa depan menjerit saat gelombang Kebenaran melonjak! Semua yang percaya pada akhirnya akan mengenal keselamatan!",
  ui_story_5065_50651003_6_dialog_content = "Bergabunglah dengan kami, dan diberkati dengan kebahagiaan abadi!",
  ui_story_5065_50651003_7_dialog_content = "Apakah kamu bersama True Order?",
  ui_story_5065_50651003_8_dialog_content = "Oh, tidak... Dia baru saja memanfaatkanku!",
  ui_story_5065_50651101_1_dialog_content = "Masih adakah anggota True Order yang menyebarkan perselisihan di Lumopolis, instruktur?",
  ui_story_5065_50651101_2_dialog_content = "Terima kasih atas bantuan Anda, Divisi Investigasi telah mengusir semua bidah aktif dari lingkungan kita.",
  ui_story_5065_50651101_3_dialog_content = "Saya mengerti Anda pasti enggan, tetapi pelatihan Anda bersama Divisi Penyelidikan akan segera berakhir.",
  ui_story_5065_50651101_4_dialog_content = "Apakah karena performa saya tidak memuaskan?",
  ui_story_5065_50651101_5_dialog_content = "Tentu saja tidak. Sekarang aku mengerti mengapa Hakim Junior sangat menekankan agar kamu tetap bersama Hall of Justice.",
  ui_story_5065_50651101_6_dialog_content = "Kemampuan kerja Anda sangat baik, dan Anda berhasil menyelesaikan banyak masalah, mengurangi beban kerja rekan-rekan Anda.",
  ui_story_5065_50651101_7_dialog_content = "Bahkan saya ingin membuatmu tetap bekerja di Divisi Investigasi seperti ini.",
  ui_story_5065_50651101_8_dialog_content = "Namun, masalah rumit lainnya muncul baru-baru ini... Banyak Eclipsites tiba-tiba muncul di Lumopolis.",
  ui_story_5065_50651101_9_dialog_content = "Semua Ks i> Semua Ksatria Lumo telah dimobilis as, tet, tetapi Cosmetics, a few key points. Containing,000000000000000000000000000000000000000000000000.",
  ui_story_5065_50651101_10_dialog_content = "Ksatria Lumo sedang mencari dukungan dari para trainee dengan keterampilan bertarung. Saya percaya kamu adalah orang yang paling cocok untuk pekerjaan ini.",
  ui_story_5065_50651101_11_dialog_content = "Prioritas utama kami saat ini adalah untuk memastikan keamanan Lumopolis Gardens.",
  ui_story_5065_50651101_12_dialog_content = "Saya ingin kamu melapor ke Kapten Penjaga Taman Lumopolis dan membantunya. Pam, apakah kamu siap melakukannya?",
  ui_story_5065_50651101_13_dialog_content = "Saya tidak keberatan! Tetapi di mana saya bisa menemukan Kapten Penjaga Taman Lumopolis?",
  ui_story_5065_50651101_14_dialog_content = "Keberadaan Lumo Knights dalam misi ini sangat rahasia dan tidak bisa dibagikan secara sembarangan.",
  ui_story_5065_50651101_15_dialog_content = "Tapi dia meninggalkanmu dengan teka-teki—",
  ui_story_5065_50651101_16_dialog_content = "Dia berada di \"tempat terdekat dengan langit.\"",
  ui_story_5065_50651101_17_dialog_content = "Teka-teki... Apakah dia sedang mengujiku?",
  ui_story_5065_50651101_18_dialog_content = "Itu salah satu cara melihatnya. Tapi dengan kemampuanmu, seharusnya kamu bisa menemukan lokasi yang ditunjukkan teka-teki itu segera, bukan?",
  ui_story_5065_50651101_19_dialog_content = "A-akan kucoba semampuku!",
  ui_story_5065_50651102_1_dialog_content = "Salam! Maaf, apakah Anda Kapten Penjaga Taman Lumopolis?",
  ui_story_5065_50651102_2_dialog_content = "Siapa kamu...?",
  ui_story_5065_50651102_3_dialog_content = "Namaku Paloma. Aku seorang pemula.",
  ui_story_5065_50651102_4_dialog_content = "Kamu Pam, kan? Aku sudah dengar tentangmu dari mentormu. Sepertinya teka-teki itu sama sekali tidak bisa membuatmu bingung.",
  ui_story_5065_50651102_5_dialog_content = "Selamat, kamu berhasil lulus ujian pertama.",
  ui_story_5065_50651102_6_dialog_content = "Situasi cukup mendesak saat ini, jadi saya harus mengirim Anda untuk memeriksa area secepat mungkin. Semoga tidak masalah bagi Anda.",
  ui_story_5065_50651102_7_dialog_content = "Aku sama sekali tidak keberatan! Aku senang untuk segera mulai dan membantu menghilangkan ancaman ini!",
  ui_story_5065_50651102_8_dialog_content = "Baiklah. Misi kamu cukup sederhana—saya harap kamu bisa pergi ke Akademi Dawn dan menyelidiki apakah ada tempat persembunyian Eclipsite di sana.",
  ui_story_5065_50651102_9_dialog_content = "Akademi Dawn... Aku tidak akan membiarkan Eclipsite menghancurkan lorong-lorong pembelajaran tempat aku dulu belajar!",
  ui_story_5065_50651201_1_dialog_content = "Selamat pagi, Kapten Penjaga!",
  ui_story_5065_50651201_2_dialog_content = "Selamat pagi, aku dengar kamu menyelamatkan sekelompok junior dari Eclipsites?",
  ui_story_5065_50651201_3_dialog_content = "Demi White Night di atas! Melindungi orang yang tidak bersalah dan membasmi Eclipsite... Aku hanya melakukan apa yang seharusnya dilakukan!",
  ui_story_5065_50651201_4_dialog_content = "Tidak perlu merendah. Awalnya, aku pikir pujian mentormu terlalu berlebihan, tapi sekarang aku melihat bahwa mereka memang tepat.",
  ui_story_5065_50651201_5_dialog_content = "Berdasarkan laporan patroli yang kamu ajukan, apakah kamu menyimpulkan bahwa tidak ada tempat persembunyian bagi Eclipsite di Akademi Dawn?",
  ui_story_5065_50651201_6_dialog_content = "Meskipun masih ada penampakan Eclipsites yang sesekali membuat masalah di Taman Lumopolis, tampaknya mereka tidak menyusup dari dalam.",
  ui_story_5065_50651201_7_dialog_content = "Dalam hal ini, akan sia-sia jika kamu tetap di sini.",
  ui_story_5065_50651201_8_dialog_content = "Bagaimana kalau begini? Kamu pergi menemui Komandan Kesatria Hutan dan lihat apakah ada tempat persembunyian Eclipsite di wilayahnya.",
  ui_story_5065_50651201_9_dialog_content = "Dia berada di \"tempat menghadap bagian depan timbangan\"...",
  ui_story_5065_50651201_10_dialog_content = "Teka-teki lainnya...?",
  ui_story_5065_50651202_1_dialog_content = "Salam! Permisi, apakah Anda Komandan Ksatria Hutan?",
  ui_story_5065_50651202_2_dialog_content = "Hai! Kamu pasti Pam!",
  ui_story_5065_50651202_3_dialog_content = "Hmm, kamu terlihat seperti anak yang baik. Aku sudah menantikan untuk bertemu denganmu!",
  ui_story_5065_50651202_4_dialog_content = "Di mana saya harus memulai penyelidikan saya, Komandan Ksatria?",
  ui_story_5065_50651202_5_dialog_content = "Pam, kamu cukup bersemangat, ya?",
  ui_story_5065_50651202_6_dialog_content = "Baiklah, mari kita lihat... Hmmm, sepertinya ada sedikit kekurangan tenaga kerja di sekitar tempat tinggal bangsawan.",
  ui_story_5065_50651202_7_dialog_content = "Jadi, Pam, aku butuh kamu untuk mendukung patroli dan investigasi di sana. Dan pastikan untuk tetap aman!",
  ui_story_5065_50651204_1_dialog_content = "Oh tidak! Dengan bantuanmu, Pam, penyelidikan ini benar-benar berjalan lebih cepat.",
  ui_story_5065_50651204_2_dialog_content = "Ternyata tempat persembunyian Eclipsite tidak dekat dengan area pemukiman, ya? Itu lega sekali.",
  ui_story_5065_50651204_3_dialog_content = "Nah, itu hanya menyisakan satu tempat...",
  ui_story_5065_50651204_4_dialog_content = "Alun-alun dekat patung skala, jalur penting menuju Lumopolis Bawah, memang patut untuk dijelajahi.",
  ui_story_5065_50651204_5_dialog_content = "Pam, sekarang tugasmu untuk menyelidiki di sana.",
  ui_story_5065_50651301_1_dialog_content = "Huh... Ini benar-benar bikin pusing...",
  ui_story_5065_50651301_2_dialog_content = "Ada masalah, Komandan Ksatria?",
  ui_story_5065_50651301_3_dialog_content = "Kami menangkap Eclipsite yang bisa berbicara dalam bahasa Universese dan berencana untuk menginterogasinya secara mendalam tentang bagaimana ia menyelinap masuk ke Lumopolis.",
  ui_story_5065_50651301_4_dialog_content = "Tapi Eclipsite itu tidak mau mengucapkan sepatah kata pun, tidak peduli apa...",
  ui_story_5065_50651301_5_dialog_content = "Hmm, aku ingin tahu apakah ada cara lain untuk membuatnya berbicara?",
  ui_story_5065_50651301_6_dialog_content = "Oh ya! Sekarang setelah kamu menyebutkannya, tiba-tiba aku ingat trik rakyat yang sudah lama ada.",
  ui_story_5065_50651301_7_dialog_content = "Dikatakan bahwa menyiramkan Esensi Rumput Chattergrass pada Timbangan Emas dan kemudian menekannya di kepala pelaku akan membuat mereka berbicara.",
  ui_story_5065_50651301_8_dialog_content = "Aku tidak begitu yakin jika trik ini akan berhasil pada Eclipsite.",
  ui_story_5065_50651301_9_dialog_content = "Seharusnya berat emas bukan masalah, tapi di mana saya bisa menemukan Esensi Chattergrass?",
  ui_story_5065_50651301_10_dialog_content = "Mmm, saya yakin para guru di Dawn Academy pasti tahu cara menyuling Esensi Chattergrass.",
  ui_story_5065_50651301_11_dialog_content = "Dan, agar trik itu berhasil, Berat Emas haruslah yang diperoleh dari timbangan di depan Aula Keadilan.",
  ui_story_5065_50651301_12_dialog_content = "Itu tidak terdengar terlalu sulit. Aku akan membantu kamu mencarinya!",
  ui_story_5065_50651302_1_dialog_content = "Fiuh! Aku mendapatkan pemberat emas!",
  ui_story_5065_50651302_2_dialog_content = "Kini yang tersisa hanyalah Esensi Chattergrass.",
  ui_story_5065_50651302_3_dialog_content = "Benar! Saatnya mencoba peruntungan dengan profesor di Dawn Academy!",
  ui_story_5065_50651303_1_dialog_content = "Pam, mengapa kamu melihat-lihat sekitar? Apakah kamu sedang mencari seseorang?",
  ui_story_5065_50651303_2_dialog_content = "Aku mencarimu, profesor! Apakah kamu kebetulan tahu tentang Esensi Chattergrass?",
  ui_story_5065_50651303_3_dialog_content = "Haha, botani adalah keahlian saya. Kamu menanyakan pada orang yang tepat.",
  ui_story_5065_50651303_4_dialog_content = "Essence Chattergrass adalah sesuatu yang saya temukan dan sintesis secara kebetulan.",
  ui_story_5065_50651303_5_dialog_content = "Demi White Night! Pasti Dewa Cahaya yang membimbing saya menemui Anda, profesor!",
  ui_story_5065_50651303_6_dialog_content = "Para Lumo Knights sangat membutuhkan esensi ini. Bisakah saya meminta Anda untuk memberikan beberapa?",
  ui_story_5065_50651303_7_dialog_content = "Tidak masalah sama sekali. Jika Anda membutuhkannya, saya bisa mengumpulkan dan mengolahnya untuk Anda kapan saja.",
  ui_story_5065_50651303_8_dialog_content = "Kebun Rumput Berkicau yang saya urus penuh dengan daun. Saya belum sempat merapikannya...",
  ui_story_5065_50651303_9_dialog_content = "Serahkan padaku, Profesor! Aku akan membantu beres-beres!",
  ui_story_5065_50651303_10_dialog_content = "Mmm, bagus sekali. Anda telah melakukan pekerjaan pembersihan yang menyeluruh—jauh lebih baik daripada junior-junior yang tidak dapat diandalkan itu.",
  ui_story_5065_50651303_11_dialog_content = "Nah, anggap saja botol Esensi Rumput Gossip ini sebagai hadiah dariku.",
  ui_story_5065_50651303_12_dialog_content = "Kapanpun kamu punya waktu luang di masa depan, mampirlah untuk menjenguk saya dan mungkin membantu merapikan halaman rumput.",
  ui_story_5065_50651304_1_dialog_content = "Oh, kau benar-benar menemukan keduanya, ya?!",
  ui_story_5065_50651304_2_dialog_content = "Dan Anda berhasil melakukannya dalam waktu yang begitu singkat...",
  ui_story_5065_50651304_3_dialog_content = "Pam, kamu sekali lagi telah memberikan bantuan besar untukku!",
  ui_story_5065_50651304_4_dialog_content = "Huh, aku mulai merasa agak ragu untuk membiarkanmu pergi.",
  ui_story_5065_50651304_5_dialog_content = "Setelah pelatihanmu selesai, apakah kamu ingin menjadi anggota dari kami, Ksatria Lumo?",
  ui_story_5065_50651304_6_dialog_content = "Pastikan untuk memikirkannya dengan serius, ya?",
  ui_story_5065_50651401_1_dialog_content = "Hei, Pam, bagaimana hasilnya? Menemukan tempat persembunyian Eclipsites?",
  ui_story_5065_50651401_2_dialog_content = "Saya percaya situasi di sini sangat mirip dengan yang saya alami di Lumopolis Gardens.",
  ui_story_5065_50651401_3_dialog_content = "Meskipun ada sejumlah Eclipsite nakal di area tersebut, aku tidak menemukan tempat persembunyian yang bisa dianggap sebagai tempat mereka bersembunyi.",
  ui_story_5065_50651401_4_dialog_content = "Karena mereka tidak berasal dari Taman Lumopolis atau Halaman Lumopolis, hanya ada satu kemungkinan yang tersisa.",
  ui_story_5065_50651401_5_dialog_content = "Aku tahu kamu telah berusaha keras beberapa hari ini.",
  ui_story_5065_50651401_6_dialog_content = "Tapi sekarang, aku masih membutuhkan bantuanmu untuk membantu Komandan Water Knight di Lower Lumopolis.",
  ui_story_5065_50651401_7_dialog_content = "Jika Eclipsite benar-benar bersembunyi di Lower Lumopolis, aku sedikit khawatir tentang dia yang berada di sana sendirian.",
  ui_story_5065_50651401_8_dialog_content = "Dan, tentu saja, jangan biarkan dia tahu apa yang baru saja aku katakan.",
  ui_story_5065_50651401_9_dialog_content = "Ah, hampir saja aku lupa memberitahumu bahwa Water Knight Commander berada di \"tempat di antara dua mata hijau.\"",
  ui_story_5065_50651401_10_dialog_content = "Mengerti. Saya akan mencari Komandan Ksatria Air dan membantunya menghancurkan Eclipsites serta titik kumpul tersembunyi mereka!",
  ui_story_5065_50651402_1_dialog_content = "Hah?",
  ui_story_5065_50651402_2_dialog_content = "Ada apa, Nona? Kenapa kau menatapku dengan aneh? Ada sesuatu yang mengganggumu?",
  ui_story_5065_50651402_3_dialog_content = "Apakah saya di tempat yang benar? Atau mungkinkah... Anda adalah Komandan Ksatria Air?",
  ui_story_5065_50651402_4_dialog_content = "Yep, aku.",
  ui_story_5065_50651402_5_dialog_content = "Ah-ha, aku paham sekarang! Kamu pasti orang yang mereka sebut-sebut—Pam! Senang akhirnya bisa bertemu denganmu!",
  ui_story_5065_50651402_6_dialog_content = "Memang benar saat ini ada kekurangan tenaga di Lower Lumopolis, jadi mungkin aku harus merepotkan kamu untuk patroli di luar...",
  ui_story_5065_50651402_7_dialog_content = "Tidak ada masalah sama sekali! Jika kamu ingin aku patroli di suatu area, cukup beri aku perintahnya!",
  ui_story_5065_50651402_8_dialog_content = "Biarkan saya melihat... satu-satunya area permukiman yang belum diperiksa adalah di dekat patung skala. Jadi, itulah tempat Anda perlu berpatroli!",
  ui_story_5065_50651402_9_dialog_content = "Bukan masalah!",
  ui_story_5065_50651403_1_dialog_content = "Lebih banyak Eclipsite di sini daripada di Kebun Lumopolis, dan mereka juga jauh lebih kuat.",
  ui_story_5065_50651403_2_dialog_content = "Mungkinkah titik pertemuan rahasia mereka berada di dekat sini?",
  ui_story_5065_50651404_1_dialog_content = "Auuuum!",
  ui_story_5065_50651404_2_dialog_content = "Inilah akhirnya!",
  ui_story_5065_50651404_3_dialog_content = "Fiuh... Aku tidak pernah mengira Eclipsites akan bersembunyi di rumah biasa seperti ini.",
  ui_story_5065_50651404_4_dialog_content = "...",
  ui_story_5065_50651404_5_dialog_content = "Siapa di sana? Tunjukkan dirimu!",
  ui_story_5065_50651404_6_dialog_content = "Aku akan habis-habisan melawanmu!!!",
  ui_story_5065_50651404_7_dialog_content = "Kamu rupanya!",
  ui_story_5065_50651404_8_dialog_content = "... Kamu tahu aku?",
  ui_story_5065_50651404_9_dialog_content = "Tidak ingat? Ketika aku menyampaikan khotbah di alun-alun kota beberapa hari lalu, kamu bilang...",
  ui_story_5065_50651404_10_dialog_content = "Sayangnya, sungguh disayangkan bahwa takdir seseorang tidak bisa diubah melalui keyakinan.",
  ui_story_5065_50651404_11_dialog_content = "Saat itu, aku benar-benar ingin bertanya kenapa kau mengatakan hal seperti itu dan apa yang akan kau lakukan mengenai hal itu, tapi kau pergi begitu terburu-buru...",
  ui_story_5065_50651404_12_dialog_content = "*Batuk* Dan sekarang kamu melihatnya.",
  ui_story_5065_50651404_13_dialog_content = "Ya... Aku yang menyembunyikan Eclipsite di rumahku! Aku ingin membalas dendam pada Lumopolis! Ayo! Hukum aku! Batuk...",
  ui_story_5065_50651404_14_dialog_content = "Kamu terluka? Mohon maaf, aku tidak menyakitimu tadi, kan?",
  ui_story_5065_50651404_15_dialog_content = "Berhenti jadi munafik, uhuk... K-Kenapa kamu ingin menyembuhkanku?",
  ui_story_5065_50651404_16_dialog_content = "Aku tidak tahu apa yang terjadi di masa lalumu, dan aku juga tidak tahu mengapa kau ingin membalas dendam pada Lumopolis.",
  ui_story_5065_50651404_17_dialog_content = "Tapi kamu tetap warga negara sejawatku! Seorang warga yang hidup dan bernafas!",
  ui_story_5065_50651404_18_dialog_content = "Demi White Night! Dewa Cahaya mengajarkan kita untuk mencintai dan membantu sesama warga, serta menunjukkan kasih sayang kepada mereka...",
  ui_story_5065_50651404_19_dialog_content = "Aku tidak akan tinggal diam dan menyaksikan kamu menderita!",
  ui_story_5065_50651404_20_dialog_content = "Siapa kau sebenarnya?",
  ui_story_5065_50651404_21_dialog_content = "Namaku Paloma, tapi kamu bisa memanggilku Pam. Aku adalah seorang inisiat dari kuil.",
  ui_story_5065_50651404_22_dialog_content = "Heh... Jadi, ternyata anak-anak polos dan berhati baik seperti kamu memang ada di dunia ini.",
  ui_story_5065_50651404_23_dialog_content = "Andai saja dulu aku bertemu dengan orang-orang yang tulus seperti kamu, mungkin aku tidak akan sampai pada titik ini hari ini...",
  ui_story_5065_50651404_24_dialog_content = "Namun, Nak, di kota seperti ini, kepolosan dan kebaikan hati tidak akan membawa kamu jauh.",
  ui_story_5065_50651404_25_dialog_content = "Semoga kamu... tidak menghadapi ketidakadilan yang sama seperti yang aku alami...",
  ui_story_5065_50651404_26_dialog_content = "A-Apa yang kamu rencanakan?",
  ui_story_5065_50651404_27_dialog_content = "Terima kasih telah membiarkan saya merasakan sedikit kehangatan di saat-saat terakhir hidup saya.",
  ui_story_5065_50651404_28_dialog_content = "Selamat tinggal, nak.",
  ui_story_5065_50651404_29_dialog_content = "<color=#e8d9bb>Pria tua itu menggali pinggangnya dan mengeluarkan belati, lalu dengan ganas menusukkannya ke dalam jantungnya sendiri.</color>",
  ui_story_5065_50651404_30_dialog_content = "...!!!",
  ui_story_5065_50651404_31_dialog_content = "Mengapa... Mengapa kamu melakukan ini...?",
  ui_story_5065_50651501_1_dialog_content = "Pam... A-Apa ini kebetulan!",
  ui_story_5065_50651501_2_dialog_content = "(Hah, kamu memang buruk berbohong, Irridon...)",
  ui_story_5065_50651501_3_dialog_content = "Wanita Irridon? Apa yang Anda lakukan di sini juga...?",
  ui_story_5065_50651501_4_dialog_content = "Aku... Aku di sini untuk bekerja, tentu saja! Justice Knights dikenal sering berlarian seperti ini sesekali.",
  ui_story_5065_50651501_5_dialog_content = "Sayangnya, aku kehilangan file yang sangat penting, dan sekarang aku sedang mencarinya dengan putus asa.",
  ui_story_5065_50651501_6_dialog_content = "Katanya kamu sangat pandai menemukan barang yang hilang, Pam... Bisakah kamu membantuku mencari?",
  ui_story_5065_50651501_7_dialog_content = "Berkas yang sangat penting?",
  ui_story_5065_50651501_8_dialog_content = "Ya! Ini sangat penting! Jika saya tidak menemukannya, mereka mungkin akan mengusir saya dari Hall of Justice!",
  ui_story_5065_50651501_9_dialog_content = "Sigh, jika itu benar-benar penting, seharusnya kamu merawatnya dengan lebih baik sejak awal.",
  ui_story_5065_50651501_10_dialog_content = "Kemana saja kamu baru-baru ini?",
  ui_story_5065_50651501_11_dialog_content = "Nah, saya baru saja berjalan ke sini dari patung timbangan itu.",
  ui_story_5065_50651501_12_dialog_content = "... Baiklah, aku akan membantumu.",
  ui_story_5065_50651502_1_dialog_content = "Ugh, kenapa ada yang tega membuang potongan kertas begitu banyak di jalan yang rapi dan bersih ini?",
  ui_story_5065_50651502_2_dialog_content = "Tunggu, mungkinkah berkas itu tersembunyi di bawah tumpukan kertas ini?",
  ui_story_5065_50651502_3_dialog_content = "Saya tidak bisa mengesampingkan kemungkinan apa pun, jadi saya harus membersihkan tempat ini dengan baik!",
  ui_story_5065_50651502_4_dialog_content = "Tidak ada apa-apa di sini...",
  ui_story_5065_50651502_5_dialog_content = "Kurasa aku harus terus menatap ke depan.",
  ui_story_5065_50651503_1_dialog_content = "Mengapa belum ada yang membersihkan semua daun ini juga?",
  ui_story_5065_50651503_2_dialog_content = "Aduh... Aku masih belum bisa mengesampingkan kemungkinan-kemungkinan lain.",
  ui_story_5065_50651503_3_dialog_content = "Membersihkan daun-daun ini seharusnya tidak memakan waktu lama kok.",
  ui_story_5065_50651503_4_dialog_content = "Fiuh! Jauh lebih bersih!",
  ui_story_5065_50651503_5_dialog_content = "Tapi masih belum ada tanda-tanda file itu...",
  ui_story_5065_50651504_1_dialog_content = "Syukurlah! Ini seharusnya berkas yang hilang!",
  ui_story_5065_50651504_2_dialog_content = "Tapi itu ada di tempat terbuka dekat patung timbangan... Bagaimana mungkin Lady Irridon melewatkannya?",
  ui_story_5065_50651505_1_dialog_content = "Wanita Irridon, apakah ini berkas yang hilang milik Anda?",
  ui_story_5065_50651505_2_dialog_content = "... Apakah kamu sempat melihat isinya?",
  ui_story_5065_50651505_3_dialog_content = "Mungkin aku tidak secara resmi bekerja di Hall of Justice, tapi bahkan aku tahu bahwa melihat file pribadi itu tidak dapat diterima.",
  ui_story_5065_50651505_4_dialog_content = "Aku yakin kamu seharusnya yang memeriksanya.",
  ui_story_5065_50651505_5_dialog_content = "Seharusnya tidak menjadi masalah. Bahkan, saya berharap Anda mau melihat lebih dekat pada file tersebut.",
  ui_story_5065_50651505_6_dialog_content = "A-Aku...? Tapi kenapa?",
  ui_story_5065_50651505_7_dialog_content = "Buka saja dan lihat!",
  ui_story_5065_50651505_8_dialog_content = "\"Keluarga Pyrrhus, bersama keluarga Gautier, menggunakan Eclipsite yang ditingkatkan untuk mengatur aksi pemberontakan keras...\"",
  ui_story_5065_50651505_9_dialog_content = "\"Setiap anggota dari keluarga mereka masing-masing telah dijatuhi hukuman mati. Jika ada perlawanan lebih lanjut, mereka akan dieksekusi di tempat?!\"",
  ui_story_5065_50651505_10_dialog_content = "Pasti ada kesalahan, Wanita Irridon!!",
  ui_story_5065_50651505_11_dialog_content = "Pam, apa kamu tidak merasa... bahwa kamu pernah melihat keputusan seperti ini sebelumnya?",
  ui_story_5065_50651505_12_dialog_content = "A-Apakah aku? Rasanya memang seperti pernah melihat ini sebelumnya, tapi di mana? Tunggu... Kamu mencoba menanamkan ide itu di pikiranku, bukan?",
  ui_story_5065_50651505_13_dialog_content = "Kamu sebenarnya tidak pernah kehilangan file ini! Kamu ingin aku menemukannya dan membacanya, bukan?",
  ui_story_5065_50651505_14_dialog_content = "Tolong berhenti mencoba menghindarinya, Pam. Semuanya seharusnya sudah sangat jelas di pikiranmu sekarang, bukan?",
  ui_story_5065_50651505_15_dialog_content = "Wanita Irridon, saya tidak takut akan kesulitan maupun penghinaan...",
  ui_story_5065_50651505_16_dialog_content = "Tapi saya tidak akan mengizinkan Anda untuk mengejek keluarga saya!",
  ui_story_5065_50651505_17_dialog_content = "Pam...",
  ui_story_5065_50651505_18_dialog_content = "Apakah benar-benar tidak ada cara untuk membuatnya menerima kenyataan?",
  ui_story_5065_50651505_19_dialog_content = "Aku sangat memahaminya. Kehilangan dirinya dalam hari-hari penuh harapan ini pasti memberinya banyak kenyamanan dan kebahagiaan.",
  ui_story_5065_50651505_20_dialog_content = "Tapi demi Dewa Cahaya, aku bersumpah bahwa aku tidak akan pernah menyerah padanya.",
  ui_story_5065_50651505_21_dialog_content = "Jika sekali saja tidak cukup, maka aku akan terus mencoba lagi dan lagi. Tidak peduli berapa kali pun yang diperlukan...",
  ui_story_5065_50651505_22_dialog_content = "Suatu hari nanti kita akan berhasil.",
  ui_story_5065_50651505_23_dialog_content = "Meskipun itu berarti... Menjadi musuh sekali lagi.",
  ui_story_5065_50651601_1_dialog_content = "Pam!",
  ui_story_5065_50651601_2_dialog_content = "Knight Commander... Saya sangat minta maaf!",
  ui_story_5065_50651601_3_dialog_content = "Mengapa kamu minta maaf?",
  ui_story_5065_50651601_4_dialog_content = "Selama tugas terakhir saya, saya... saya tidak dapat menghentikan tersangka untuk mengakhiri hidupnya sendiri, dan gagal untuk memahami alasan dia menyembunyikan Eclipsite di rumahnya.",
  ui_story_5065_50651601_5_dialog_content = "Menemukan pelakunya saja sudah mengesankan. Serahkan sisanya kepada Hall of Justice.",
  ui_story_5065_50651601_6_dialog_content = "Tapi saat ini, ada tugas yang lebih mendesak untuk kamu.",
  ui_story_5065_50651601_7_dialog_content = "Berdasarkan investigasi kami, mentor Anda terlibat dalam pengkhianatan. Kami memiliki bukti kuat dan perlu menangkapnya segera!",
  ui_story_5065_50651601_8_dialog_content = "Namun, mentor Anda adalah salah satu anggota paling terampil di Divisi Investigasi. Bergerak tanpa rencana yang solid sangat berisiko.",
  ui_story_5065_50651601_9_dialog_content = "Dan kamu, sebagai trainee yang ditugaskan kepadanya, memiliki alasan yang valid untuk mendekatinya...",
  ui_story_5065_50651601_10_dialog_content = "Kamu ingin aku... Menangkap instrukturku?",
  ui_story_5065_50651601_11_dialog_content = "Misi ini sangat menantang, tapi jika kamu tidak melakukannya, kamu mungkin akan terlihat seperti kaki tangan...",
  ui_story_5065_50651601_12_dialog_content = "Apakah Anda benar-benar dapat menemukan cukup bukti untuk menyalahkan dia? Apakah surat perintah penangkapan ini... Sudah disetujui oleh Penguasa Kota?",
  ui_story_5065_50651601_13_dialog_content = "Tentu saja, saya bisa memverifikasi semua yang Anda sebutkan satu per satu.",
  ui_story_5065_50651601_14_dialog_content = "Tapi sebelumnya, kamu harus memberi tahu saya, apakah kamu ikut atau tidak dalam misi ini?",
  ui_story_5065_50651601_15_dialog_content = "Demi White Night! Jika instrukturku benar-benar bersalah melakukan kejahatan yang begitu keji...",
  ui_story_5065_50651601_16_dialog_content = "Maka saya memiliki kewajiban untuk menangkapnya!",
  ui_story_5065_50651602_1_dialog_content = "Pam, ada apa? Kamu biasanya tidak terlihat begitu bermasalah.",
  ui_story_5065_50651602_2_dialog_content = "... Bagaimana kamu bisa melakukan hal seperti itu?",
  ui_story_5065_50651602_3_dialog_content = "Hah?",
  ui_story_5065_50651602_4_dialog_content = "Saya bersyukur atas bimbingan yang telah Anda berikan beberapa hari terakhir ini, tapi...",
  ui_story_5065_50651602_5_dialog_content = "Mohon maafkan saya! Saya tidak punya pilihan selain membayar Anda dengan cara ini!",
  ui_story_5065_50651602_6_dialog_content = "Tahan! TAHAN!",
  ui_story_5065_50651602_7_dialog_content = "Ya ampun, beberapa gerakan lembut saja sudah cukup. Kenapa harus berlebihan?",
  ui_story_5065_50651602_8_dialog_content = "Meskipun saya bisa menyelamatkan nyawa, kamu tidak boleh sembrono.",
  ui_story_5065_50651602_9_dialog_content = "Maaf, saya ingin menggunakan kesempatan ini untuk menguji kemampuan tempur Pam.",
  ui_story_5065_50651602_10_dialog_content = "Selamat, kamu telah lulus penilaian pada tahap ini!",
  ui_story_5065_50651602_11_dialog_content = "Penilaian? Jadi... Anda tidak pernah merencanakan pengkhianatan? Lalu bagaimana dengan surat perintah penangkapan dan semua bukti itu?",
  ui_story_5065_50651602_12_dialog_content = "Itu semua palsu, tahu. Nantinya mentor Anda akan mengajari Anda cara membedakan surat perintah penangkapan yang asli!",
  ui_story_5065_50651602_13_dialog_content = "Ehem, tapi kami tidak berniat menipu Anda, lho.",
  ui_story_5065_50651602_14_dialog_content = "Kuil Lumopolis mewajibkan format penilaian ini untuk melihat apakah kamu akan membiarkan emosi menghalangi...",
  ui_story_5065_50651602_15_dialog_content = "Kemampuan Anda untuk menyingkirkan emosi pribadi dalam menghadapi keputusan penting dan bertahan adalah kualitas yang tepat yang dibutuhkan oleh staf Kuil Lumopolis.",
  ui_story_5065_50651602_16_dialog_content = "Lulus dalam penilaian ini berarti kau semakin dekat untuk bekerja di Kuil Lumopolis.",
  ui_story_5065_50651602_17_dialog_content = "Oh, syukur kepada Cahaya! Aku sangat lega bahwa kamu ternyata bukan pengkhianat!",
  ui_story_5065_50651602_18_dialog_content = "Namun…",
  ui_story_5065_50651602_19_dialog_content = "Apa yang harus (yaitga) yang harus saya lakukan jika ada sesuatu yang salah dengan pesanan saya, atau surat per advances, seperti dalam kasus penangkasan atau per \n",
  ui_story_5065_50651602_20_dialog_content = "Sh-Haruskah saya tetap membawanya tanpa bertanya seperti ini?",
  ui_story_5065_50651602_21_dialog_content = "Keputusan Kuil Lumopolis mewakili kehendak Dewa Cahaya. Ada banyak tingkatan pengawasan sebelum perintah dikeluarkan.",
  ui_story_5065_50651602_22_dialog_content = "I-Begitukah...",
  ui_story_5065_50651602_23_dialog_content = "Tenang saja, hal-hal yang kamu khawatirkan tidak akan terjadi.",
  ui_story_5065_50651602_24_dialog_content = "Daripada khawatir tentang semua \"jika\" ini, lebih baik kamu tanyakan pada mentor kamu lebih lanjut tentang karier masa depanmu.",
  ui_story_5065_50651602_25_dialog_content = "... Aku mengerti!",
  ui_story_5065_50651602_26_dialog_content = "Jika suatu hari nanti aku benar-benar menjadi seorang cendekiawan, aku akan mengabdikan seluruh hidupku untuk melayani Dewa Cahaya!",
  ui_story_5065_50651602_27_dialog_content = "Melalui tindakanku, aku akan membawa cahaya ke setiap rumah tangga di Lumopolis dan melindungi rumah indah kita!",
  ui_story_5065_50651602_28_dialog_content = "Bagus, aku tidak sabar menunggu hari saat kamu menjadi biarawati resmi.",
  ui_story_5065_50651602_29_dialog_content = "Tapi dalam periode magang yang akan datang, kamu akan menghadapi banyak tantangan, jadi kamu harus tetap waspada.",
  ui_story_5065_50651602_30_dialog_content = "Terima kasih telah mengingatkanku! Aku berjanji akan bekerja lebih keras lagi untuk menyelesaikan setiap ujian yang ada di depanku!",
  ui_story_5065_50651701_1_dialog_content = "Apakah ini hanya imajinasi? Mengapa rasanya seperti aku terus-menerus bertemu dengan orang-orang yang sama dan melakukan tugas-tugas yang sama...",
  ui_story_5065_50651701_2_dialog_content = "Aku merasa sangat pusing, dan mengerjakan tugas-tugasku menjadi semakin melelahkan...",
  ui_story_5065_50651701_3_dialog_content = "Sudah berapa lama aku menjadi inisiat sekarang? Berapa lama lagi hingga aku selesai?",
  ui_story_5065_50651701_4_dialog_content = "Kenapa aku belum naik jabatan? Apakah... Apakah karena aku masih belum cukup terampil untuk menjadi biarawati sejati?",
  ui_story_5065_50651701_5_dialog_content = "Atau mungkinkah ini benar-benar...",
  ui_story_5065_50651701_6_dialog_content = "Mimpi?",
  ui_story_5065_50651701_7_dialog_content = "Wanita Irridon?!",
  ui_story_5065_50651701_8_dialog_content = "Sejujurnya, kau menyadari keanehan dunia ini sejak lama, 'kan?",
  ui_story_5065_50651701_9_dialog_content = "Tapi selama ini kamu tidak mau menghadapi kenyataan. Bukankah begitu?",
  ui_story_5065_50651701_10_dialog_content = "T-Tidak... Aku hanya ingin bekerja keras dan mendapatkan persetujuan instruktur untuk menjadi biarawati di Lumopolis Temple. Aku hanya...",
  ui_story_5065_50651701_11_dialog_content = "Aku hanya ingin menyelamatkan keluargaku dari rasa sakit yang lebih dalam!",
  ui_story_5065_50651701_12_dialog_content = "\"Lebih sakit lagi\"?",
  ui_story_5065_50651701_13_dialog_content = "Ah, apa yang aku katakan...? Keluargaku seharusnya aman dan selamat di Halaman Lumopolis sekarang ini...",
  ui_story_5065_50651701_14_dialog_content = "Tapi mengapa rasanya seperti sudah lama sekali tidak bertemu mereka...?",
  ui_story_5065_50651701_15_dialog_content = "Mengapa terus muncul gambaran mereka ditangkap dalam pikiranku...?",
  ui_story_5065_50651701_16_dialog_content = "Gambaran itu pasti mimpi buruk yang nyata di sini, bukan, Lady Irridon?",
  ui_story_5065_50651701_17_dialog_content = "Saatnya menghadapi kenyataan, Pam.",
  ui_story_5065_50651701_18_dialog_content = "... Apakah dunia ini benar-benar hanya ilusi semata?",
  ui_story_5065_50651701_19_dialog_content = "Tapi cita-citaku sudah begitu dekat! Hanya sedikit lagi, dan aku akhirnya bisa menjadi biarawati sejati!",
  ui_story_5065_50651701_20_dialog_content = "Jika aku bangun sekarang... Apakah semua ini akan menghilang?",
  ui_story_5065_50651701_21_dialog_content = "Maafkan aku, Pam...",
  ui_story_5065_50651701_22_dialog_content = "... Apakah berkas yang kamu tunjukkan padaku juga nyata?",
  ui_story_5065_50651701_23_dialog_content = "Dengan kata lain, jika aku bangun dari mimpi ini, keluargaku tidak akan bersamaku lagi...",
  ui_story_5065_50651701_24_dialog_content = "Kalau begitu, kenapa repot-repot bangun? Aku tidak akan bisa bertahan hidup sendirian.",
  ui_story_5065_50651701_25_dialog_content = "Tidak, Pam. Kamu jauh lebih kuat daripada yang kamu tahu.",
  ui_story_5065_50651701_26_dialog_content = "Di luar dunia mimpi ini, kamu lebih kuat, lebih percaya diri, dan sepenuhnya menyadari siapa dirimu yang sebenarnya.",
  ui_story_5065_50651701_27_dialog_content = "Kamu akan bertahan, dan kehidupan yang akan kamu jalani jauh lebih indah daripada yang bisa kamu bayangkan.",
  ui_story_5065_50651701_28_dialog_content = "L-Lalu, apakah kita masih berteman di dunia nyata?",
  ui_story_5065_50651701_29_dialog_content = "... Kita hidup di dua dunia yang berbeda di luar sana, dan jarak di antara keduanya bahkan lebih besar daripada jarak antara mimpi ini dan kenyataan.",
  ui_story_5065_50651701_30_dialog_content = "Tapi aku selalu mengagumi Pam yang hidup dengan cara sendiri, bahkan di dunia yang terpisah.",
  ui_story_5065_50651701_31_dialog_content = "Dia berani mencintai dan membenci, dan jauh lebih kuat daripada seseorang yang berakar di tempat seperti diriku.",
  ui_story_5065_50651701_32_dialog_content = "Kalau saja tragedi itu tidak terjadi di masa lalu, saya yakin kita bisa menjadi teman baik.",
  ui_story_5065_50651701_33_dialog_content = "Tapi kita teman baik!",
  ui_story_5065_50651701_34_dialog_content = "A-Aku mulai mengingat hal-hal. Mereka masih sangat jauh, tapi mereka nyata.",
  ui_story_5065_50651701_35_dialog_content = "Dalam kenangan itu, kita sepakat untuk menjadi teman. Itulah mengapa kamu berusaha keras untuk membangunkan aku dari mimpi ini, bukan?",
  ui_story_5065_50651701_36_dialog_content = "Meskipun seluruh dunia ini adalah kebohongan, persahabatan kita... sangatlah nyata!",
  ui_story_5065_50651701_37_dialog_content = "...",
  ui_story_5065_50651701_38_dialog_content = "Benar. Aku tidak akan pernah lupa bahwa kau adalah teman pertamaku.",
  ui_story_5065_50651701_39_dialog_content = "Saatnya bangun!",
  ui_story_5065_50651701_40_dialog_content = "Apakah kaca pembesar itu baru saja berbicara? Dan mengapa suaranya terdengar sangat familiar...?",
  ui_story_5065_50651701_41_dialog_content = "Ketika kamu bangun, kamu akan ingat PlayerName.",
  ui_story_5065_50651701_42_dialog_content = "Meskipun, ada kemungkinan kamu bertemu dengannya jauh sebelum aku.",
  ui_story_5065_50651701_43_dialog_content = "Apakah kita akan segera bangun?",
  ui_story_5065_50651701_44_dialog_content = "Ya. Tubuhku... Semakin ringan... Aku mulai merasa agak kesepian juga...",
  ui_story_5065_50651701_45_dialog_content = "Pegang tanganku, Lady Irridon! Dengan begitu kamu tidak akan merasa kesepian lagi!",
  ui_story_5065_50651701_46_dialog_content = "...",
  ui_story_5065_50651701_47_dialog_content = "Terima kasih, temanku.",
  ui_story_5065_50651701_48_dialog_content = "Kita akan bertemu lagi!"
}
return config
